/* Return how many semantic errors use one stable diagnostic code. */
static size_t semantic_error_code_count(const FengSemanticError *errors,
                                        size_t error_count,
                                        const char *code) {
    size_t count = 0U;

    for (size_t index = 0U; index < error_count; ++index) {
        if (strcmp(errors[index].code, code) == 0) {
            ++count;
        }
    }
    return count;
}

/* Find one declared method on a type or fit by its Feng name. */
static const FengTypeMember *find_contract_method(
    const FengDecl *owner,
    const char *name) {
    FengTypeMember *const *members = NULL;
    size_t member_count = 0U;
    size_t name_length = strlen(name);

    if (owner == NULL) {
        return NULL;
    }
    if (owner->kind == FENG_DECL_TYPE) {
        members = owner->as.type_decl.members;
        member_count = owner->as.type_decl.member_count;
    } else if (owner->kind == FENG_DECL_FIT) {
        members = owner->as.fit_decl.members;
        member_count = owner->as.fit_decl.member_count;
    } else {
        return NULL;
    }
    for (size_t index = 0U; index < member_count; ++index) {
        const FengTypeMember *member = members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->as.callable.name.length == name_length &&
            memcmp(member->as.callable.name.data, name, name_length) == 0) {
            return member;
        }
    }
    return NULL;
}

/* Find one field implementation by name on a concrete type. */
static const FengTypeMember *find_contract_field(
    const FengDecl *owner,
    const char *name) {
    size_t name_length = strlen(name);

    if (owner == NULL || owner->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    for (size_t index = 0U;
         index < owner->as.type_decl.member_count;
         ++index) {
        const FengTypeMember *member = owner->as.type_decl.members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_FIELD &&
            member->as.field.name.length == name_length &&
            memcmp(member->as.field.name.data, name, name_length) == 0) {
            return member;
        }
    }
    return NULL;
}

/* Declared nominal relationships record their exact implementation members
 * independently of on-demand witness materialization. Only public relation
 * owners expose selected seal members as package implementation dependencies. */
static void test_declared_spec_relationship_records_implementation_selection(void) {
    const char *source =
        "open module demo.spec_seal.implementation_selection;\n"
        "open spec Contract {\n"
        "    seal func value(): int;\n"
        "    seal static func marker(): int;\n"
        "    seal static let markerValue: int;\n"
        "}\n"
        "open type Direct: Contract {\n"
        "    seal func value(): int { return 1; }\n"
        "    seal static func marker(): int { return 2; }\n"
        "    seal static let markerValue: int = 3;\n"
        "    seal static let unrelatedField: int = 4;\n"
        "    seal func unrelated(): int { return 3; }\n"
        "}\n"
        "open type FitValue { seal static let markerValue: int = 5; }\n"
        "open fit FitValue: Contract {\n"
        "    seal func value(): int { return 4; }\n"
        "    seal static func marker(): int { return 5; }\n"
        "    seal func unrelatedFit(): int { return 6; }\n"
        "}\n"
        "type Local: Contract {\n"
        "    seal func value(): int { return 7; }\n"
        "    seal static func marker(): int { return 8; }\n"
        "    seal static let markerValue: int = 9;\n"
        "}\n";
    FengProgram *program = parse_program_or_die(
        "spec_implementation_selection.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *direct;
    const FengDecl *fit_value;
    const FengDecl *local;
    const FengDecl *fit_decl = NULL;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    ASSERT(analysis->spec_witness_count == 0U);
    ASSERT(analysis->spec_implementation_selection_count == 9U);

    direct = find_type_decl_by_name(analysis, "Direct");
    fit_value = find_type_decl_by_name(analysis, "FitValue");
    local = find_type_decl_by_name(analysis, "Local");
    ASSERT(direct != NULL && fit_value != NULL && local != NULL);
    for (size_t index = 0U;
         index < program->declaration_count;
         ++index) {
        if (program->declarations[index]->kind == FENG_DECL_FIT) {
            fit_decl = program->declarations[index];
            break;
        }
    }
    ASSERT(fit_decl != NULL);
    ASSERT(feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_method(direct, "value")));
    ASSERT(feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_method(direct, "marker")));
    ASSERT(feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_field(direct, "markerValue")));
    ASSERT(!feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_field(direct, "unrelatedField")));
    ASSERT(!feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_method(direct, "unrelated")));
    ASSERT(feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_method(fit_decl, "value")));
    ASSERT(feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_method(fit_decl, "marker")));
    ASSERT(!feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_method(fit_decl, "unrelatedFit")));
    ASSERT(feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_field(fit_value, "markerValue")));
    ASSERT(!feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_method(local, "value")));
    ASSERT(!feng_semantic_member_is_package_spec_implementation_dependency(
        analysis, find_contract_field(local, "markerValue")));

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Type instance/static methods and target-type fit instance/static methods
 * may access seal requirements only through the corresponding spec view. */
static void test_spec_seal_member_access_from_implementation_contexts(void) {
    const char *source =
        "module demo.spec_seal.access_allowed;\n"
        "spec Hooks {\n"
        "    seal var state: int;\n"
        "    seal func read(): int;\n"
        "    seal static var shared: int;\n"
        "    seal static func phase(): int;\n"
        "}\n"
        "type Worker: Hooks {\n"
        "    var state: int = 1;\n"
        "    func read(): int { return self.state; }\n"
        "    static var shared: int = 2;\n"
        "    static func phase(): int { return 3; }\n"
        "    func use(other: Hooks): int {\n"
        "        other.state = 4;\n"
        "        return other.state + other.read();\n"
        "    }\n"
        "    static func useStatic<T: Hooks>(): int {\n"
        "        T.shared = 5;\n"
        "        return T.shared + T.phase();\n"
        "    }\n"
        "}\n"
        "fit Worker {\n"
        "    func useFromFit(other: Hooks): int { return other.read(); }\n"
        "    static func useStaticFromFit<T: Hooks>(): int {\n"
        "        return T.shared + T.phase();\n"
        "    }\n"
        "}\n";
    FengProgram *program = parse_program_or_die("spec_seal_access_allowed.ff",
                                                source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Ordinary functions, unrelated type methods, and unrelated fit methods
 * cannot access instance/static seal requirements through a spec view. */
static void test_spec_seal_member_access_rejected_outside_implementation(void) {
    static const struct {
        const char *path;
        const char *source;
    } cases[] = {
        {
            "spec_seal_top_level_field.ff",
            "module demo.spec_seal.denied_field;\n"
            "spec Hidden { seal var value: int; }\n"
            "type Box: Hidden { var value: int = 1; }\n"
            "func read(value: Hidden): int { return value.value; }\n"
        },
        {
            "spec_seal_top_level_method.ff",
            "module demo.spec_seal.denied_method;\n"
            "spec Hidden { seal func value(): int; }\n"
            "type Box: Hidden { func value(): int { return 1; } }\n"
            "func read(value: Hidden): int { return value.value(); }\n"
        },
        {
            "spec_seal_top_level_static.ff",
            "module demo.spec_seal.denied_static;\n"
            "spec Hidden { seal static func value(): int; }\n"
            "type Box: Hidden { static func value(): int { return 1; } }\n"
            "func read<T: Hidden>(): int { return T.value(); }\n"
        },
        {
            "spec_seal_unrelated_type.ff",
            "module demo.spec_seal.denied_type;\n"
            "spec Hidden { seal func value(): int; }\n"
            "type Box: Hidden { func value(): int { return 1; } }\n"
            "type Other {\n"
            "    func read(value: Hidden): int { return value.value(); }\n"
            "}\n"
        },
        {
            "spec_seal_unrelated_fit.ff",
            "module demo.spec_seal.denied_fit;\n"
            "spec Hidden { seal func value(): int; }\n"
            "type Box: Hidden { func value(): int { return 1; } }\n"
            "type Other {}\n"
            "fit Other {\n"
            "    func read(value: Hidden): int { return value.value(); }\n"
            "}\n"
        }
    };

    for (size_t index = 0U;
         index < sizeof(cases) / sizeof(cases[0]);
         ++index) {
        FengProgram *program = parse_program_or_die(cases[index].path,
                                                    cases[index].source);
        const FengProgram *programs[] = {program};
        FengSemanticAnalysis *analysis = NULL;
        FengSemanticError *errors = NULL;
        size_t error_count = 0U;

        ASSERT(!feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                      &analysis, &errors, &error_count));
        ASSERT(semantic_error_code_count(errors, error_count, "AE0708") == 1U);
        feng_semantic_errors_free(errors, error_count);
        feng_semantic_analysis_free(analysis);
        feng_program_free(program);
    }
}

