static void test_tuple_named_conversion_rules(void) {
    const char *explicit_ok =
        "module demo.main;\n"
        "type UnitA();\n"
        "type UnitB();\n"
        "type A(int, string);\n"
        "type B(int, string);\n"
        "func run(): int {\n"
        "    let unit_b: UnitB = ();\n"
        "    let unit_a: UnitA = (UnitA)unit_b;\n"
        "    let b: B = (1, \"ok\");\n"
        "    let a: A = (A)b;\n"
        "    return a.item1;\n"
        "}\n";
    const char *implicit_bad =
        "module demo.main;\n"
        "type A(int, int);\n"
        "type B(int, int);\n"
        "type UnitA();\n"
        "type UnitB();\n"
        "func run(): void {\n"
        "    let unit_b: UnitB = ();\n"
        "    let unit_a: UnitA = unit_b;\n"
        "    let b: B = (1, 2);\n"
        "    let a: A = b;\n"
        "}\n";
    const char *explicit_bad =
        "module demo.main;\n"
        "type A(int, int);\n"
        "type C(int, string);\n"
        "func run(): void {\n"
        "    let c: C = (1, \"bad\");\n"
        "    let a: A = (A)c;\n"
        "}\n";

    assert_single_source_semantic_ok("tuple_explicit_cast_ok.f", explicit_ok);
    assert_single_source_semantic_error_contains("tuple_implicit_cast_bad.f",
                                                 implicit_bad,
                                                 "does not match expected type");
    assert_single_source_semantic_error_contains("tuple_explicit_cast_bad.f",
                                                 explicit_bad,
                                                 "cast from");
}

