static void test_iterator_basic_iterable_ok(void) {
    const char *source =
        "module demo.main;\n"
        "type Result(bool, i32);\n"
        "type Cursor {\n"
        "    var pos: i32;\n"
        "    @iterator\n"
        "    func next(): Result {\n"
        "        if self.pos >= 3 { return (false, 0); }\n"
        "        let v = self.pos;\n"
        "        self.pos = self.pos + 1;\n"
        "        return (true, v);\n"
        "    }\n"
        "}\n"
        "type Container {\n"
        "    @iterable\n"
        "    func iter(): Cursor { return Cursor { pos: 0 }; }\n"
        "}\n"
        "func use(n: i32) {}\n"
        "func run(): void {\n"
        "    let c = Container {};\n"
        "    for let x in c {\n"
        "        use(x);\n"
        "    }\n"
        "}\n";

    assert_single_source_semantic_ok("iter_basic_iterable_ok.f", source);
}

