/* Verifies target-explicit priority uses the ordinary contract-aware
 * overload-overlap rule, rather than only syntax-identical parameter types. */
static void test_mixable_static_candidate_skips_explicit_overlapping_method(void) {
    const char *source =
        "module demo.mixable_explicit_overlap;\n"
        "spec Widget {}\n"
        "spec Left {}\n"
        "spec Right {}\n"
        "type Both: Left, Right {}\n"
        "type View: Widget {\n"
        "  @mixable open static func choose(target: Widget, value: Left): int { return 1; }\n"
        "}\n"
        "type Button: Widget {\n"
        "  ...: View;\n"
        "  static func choose(target: Widget, value: Right): int { return 2; }\n"
        "}\n";
    FengProgram *program = parse_program_or_die(
        "mixable_explicit_overlap.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *button;
    size_t static_choose_count = 0U;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    button = find_type_decl_by_name(analysis, "Button");
    ASSERT(button != NULL);
    for (size_t index = 0U;
         index < button->as.type_decl.member_count;
         ++index) {
        const FengTypeMember *member = button->as.type_decl.members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->is_static &&
            member->as.callable.name.length == 6U &&
            memcmp(member->as.callable.name.data, "choose", 6U) == 0) {
            ++static_choose_count;
            ASSERT(!member->is_mixin_static_wrapper);
        }
    }
    ASSERT(static_choose_count == 1U);

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Target-explicit mixable methods replace source candidates when deleting
 * their distinct receiver specs produces the same instance signature. */
static void test_mixable_instance_projection_prefers_explicit_target_method(void) {
    const char *source =
        "module demo.mixable_instance_projection;\n"
        "spec Widget { func draw(area: int): int; }\n"
        "spec ButtonWidget: Widget {}\n"
        "spec IconWidget: ButtonWidget {}\n"
        "type View: Widget {\n"
        "  @mixable open static func draw(target: Widget, area: int): int { return area + 1; }\n"
        "  @mixable open static func collect(target: Widget, values: int...): int { return 1; }\n"
        "  @mixable open static func identity<T>(target: Widget, value: T): T { return value; }\n"
        "}\n"
        "type Button: ButtonWidget {\n"
        "  ...: View;\n"
        "  @mixable open static func draw(target: ButtonWidget, area: int): int { return View.draw(target, area) + 10; }\n"
        "  @mixable open static func collect(target: ButtonWidget, values: int...): int { return View.collect(target, ...values) + 10; }\n"
        "  @mixable open static func identity<T>(target: ButtonWidget, value: T): T { return View.identity<T>(target, value); }\n"
        "}\n"
        "type Icon: IconWidget {\n"
        "  ...: Button;\n"
        "  @mixable open static func draw(target: IconWidget, area: int): int { return Button.draw(target, area) + 100; }\n"
        "}\n";
    FengProgram *program = parse_program_or_die(
        "mixable_instance_projection.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *button;
    const FengDecl *icon;
    size_t button_draw_static_count = 0U;
    size_t button_draw_instance_count = 0U;
    size_t button_collect_static_count = 0U;
    size_t button_collect_instance_count = 0U;
    size_t button_identity_static_count = 0U;
    size_t button_identity_instance_count = 0U;
    size_t icon_draw_static_count = 0U;
    size_t icon_draw_instance_count = 0U;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    button = find_type_decl_by_name(analysis, "Button");
    icon = find_type_decl_by_name(analysis, "Icon");
    ASSERT(button != NULL && icon != NULL);

    for (size_t index = 0U;
         index < button->as.type_decl.member_count;
         ++index) {
        const FengTypeMember *member = button->as.type_decl.members[index];
        const FengSlice name = member != NULL &&
                member->kind == FENG_TYPE_MEMBER_METHOD
            ? member->as.callable.name
            : (FengSlice){0};

        if (name.length == 4U && memcmp(name.data, "draw", 4U) == 0) {
            if (member->is_static) {
                ++button_draw_static_count;
                ASSERT(!member->is_mixin_static_wrapper);
            } else {
                ++button_draw_instance_count;
                ASSERT(member->is_mixin_instance_wrapper);
            }
        } else if (name.length == 7U &&
                   memcmp(name.data, "collect", 7U) == 0) {
            if (member->is_static) {
                ++button_collect_static_count;
                ASSERT(!member->is_mixin_static_wrapper);
            } else {
                ++button_collect_instance_count;
                ASSERT(member->is_mixin_instance_wrapper);
            }
        } else if (name.length == 8U &&
                   memcmp(name.data, "identity", 8U) == 0) {
            if (member->is_static) {
                ++button_identity_static_count;
                ASSERT(!member->is_mixin_static_wrapper);
            } else {
                ++button_identity_instance_count;
                ASSERT(member->is_mixin_instance_wrapper);
            }
        }
    }
    ASSERT(button_draw_static_count == 1U);
    ASSERT(button_draw_instance_count == 1U);
    ASSERT(button_collect_static_count == 1U);
    ASSERT(button_collect_instance_count == 1U);
    ASSERT(button_identity_static_count == 1U);
    ASSERT(button_identity_instance_count == 1U);

    for (size_t index = 0U;
         index < icon->as.type_decl.member_count;
         ++index) {
        const FengTypeMember *member = icon->as.type_decl.members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->as.callable.name.length == 4U &&
            memcmp(member->as.callable.name.data, "draw", 4U) == 0) {
            if (member->is_static) {
                ++icon_draw_static_count;
                ASSERT(!member->is_mixin_static_wrapper);
            } else {
                ++icon_draw_instance_count;
                ASSERT(member->is_mixin_instance_wrapper);
            }
        }
    }
    ASSERT(icon_draw_static_count == 1U);
    ASSERT(icon_draw_instance_count == 1U);

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Multiple sources retain no implicit priority: equal instance projections
 * conflict, while distinct projections remain ordinary instance overloads. */
static void test_mixable_multiple_source_projection_boundaries(void) {
    const char *conflicting =
        "module demo.mixable_multi_projection_conflict;\n"
        "spec Marker {}\n"
        "type Left: Marker { @mixable open static func pick(target: Marker, value: int): int { return value + 1; } }\n"
        "type Right: Marker { @mixable open static func pick(target: Marker, value: int): int { return value + 2; } }\n"
        "type Combined: Marker { ...: Left; ...: Right; }\n";
    const char *overloaded =
        "module demo.mixable_multi_projection_overload;\n"
        "spec Marker {}\n"
        "type Left: Marker { @mixable open static func pick(target: Marker, value: int): int { return value + 1; } }\n"
        "type Right: Marker { @mixable open static func pick(target: Marker, value: string): string { return value; } }\n"
        "type Combined: Marker { ...: Left; ...: Right; }\n";
    FengProgram *program = parse_program_or_die(
        "mixable_multi_projection_conflict.ff", conflicting);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    bool found_instance_conflict = false;

    ASSERT(!feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                  &analysis, &errors, &error_count));
    for (size_t index = 0U; index < error_count; ++index) {
        if (strcmp(errors[index].code, "AE0508") == 0) {
            found_instance_conflict = true;
        }
    }
    ASSERT(found_instance_conflict);
    feng_semantic_errors_free(errors, error_count);
    feng_program_free(program);

    program = parse_program_or_die(
        "mixable_multi_projection_overload.ff", overloaded);
    programs[0] = program;
    analysis = NULL;
    errors = NULL;
    error_count = 0U;
    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    {
        const FengDecl *combined = find_type_decl_by_name(analysis, "Combined");
        size_t static_pick_count = 0U;
        size_t instance_pick_count = 0U;

        ASSERT(combined != NULL);
        for (size_t index = 0U;
             index < combined->as.type_decl.member_count;
             ++index) {
            const FengTypeMember *member =
                combined->as.type_decl.members[index];

            if (member == NULL ||
                member->kind != FENG_TYPE_MEMBER_METHOD ||
                member->as.callable.name.length != 4U ||
                memcmp(member->as.callable.name.data, "pick", 4U) != 0) {
                continue;
            }
            if (member->is_static) {
                ++static_pick_count;
            } else {
                ++instance_pick_count;
            }
        }
        ASSERT(static_pick_count == 2U);
        ASSERT(instance_pick_count == 2U);
    }
    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Static propagation and instance derivation remain complete across layers. */
static void test_mixable_generates_static_and_instance_wrapper_chain(void) {
    const char *source =
        "module demo.mixable_chain;\n"
        "spec Widget { func draw(area: int): int; func log(args: string...): void; }\n"
        "type View: Widget {\n"
        "  @mixable open static func draw(target: Widget, area: int): int { return area; }\n"
        "  @mixable open static func log(target: Widget, args: string...): void {}\n"
        "}\n"
        "type Button: Widget { ...: View; }\n"
        "type IconButton: Widget { ...: Button; }\n";
    FengProgram *program = parse_program_or_die("mixable_chain.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *view;
    const FengDecl *button;
    const FengDecl *icon;
    const FengTypeMember *view_static;
    const FengTypeMember *view_instance;
    const FengTypeMember *button_static;
    const FengTypeMember *button_instance;
    const FengTypeMember *icon_static;
    const FengTypeMember *icon_instance;
    const FengTypeMember *icon_log;
    const FengStmt *log_forward;
    const FengExpr *log_call;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    view = find_type_decl_by_name(analysis, "View");
    button = find_type_decl_by_name(analysis, "Button");
    icon = find_type_decl_by_name(analysis, "IconButton");
    view_static = find_type_method_named(view, "draw", true);
    view_instance = find_type_method_named(view, "draw", false);
    button_static = find_type_method_named(button, "draw", true);
    button_instance = find_type_method_named(button, "draw", false);
    icon_static = find_type_method_named(icon, "draw", true);
    icon_instance = find_type_method_named(icon, "draw", false);
    ASSERT(view_static != NULL && view_instance != NULL);
    ASSERT(button_static != NULL && button_instance != NULL);
    ASSERT(icon_static != NULL && icon_instance != NULL);
    ASSERT(view_static->is_mixable);
    ASSERT(!view_instance->is_mixable && view_instance->is_mixin_instance_wrapper);
    ASSERT(button_static->is_mixable && button_static->is_mixin_static_wrapper);
    ASSERT(!button_instance->is_mixable && button_instance->is_mixin_instance_wrapper);
    ASSERT(icon_static->is_mixable && icon_static->is_mixin_static_wrapper);
    ASSERT(button_static->mixin_source_member == view_static);
    ASSERT(icon_static->mixin_source_member == button_static);
    ASSERT(button_instance->mixin_source_member == button_static);
    ASSERT(view_static->as.callable.param_count == 2U);
    ASSERT(view_instance->as.callable.param_count == 1U);
    ASSERT(icon_instance->as.callable.param_count == 1U);

    icon_log = find_type_method_named(icon, "log", false);
    ASSERT(icon_log != NULL);
    ASSERT(icon_log->as.callable.params[0].is_variadic);
    log_forward = icon_log->as.callable.body->statements[0];
    ASSERT(log_forward->kind == FENG_STMT_EXPR);
    log_call = log_forward->as.expr;
    ASSERT(log_call->kind == FENG_EXPR_CALL);
    ASSERT(log_call->as.call.arg_count == 2U);
    ASSERT(log_call->as.call.args[1]->is_prepacked_variadic_arg);

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Seal mixable methods use the existing wrapper chain while direct targets
 * gain only the compile-time source-call authorization defined by the mix. */
static void test_mixable_seal_generates_private_wrappers_and_direct_access(void) {
    const char *source =
        "module demo.mixable_seal;\n"
        "spec Widget {}\n"
        "type View: Widget {\n"
        "  @mixable seal static func draw(target: Widget, value: int): int { return value + 1; }\n"
        "}\n"
        "type Button: Widget {\n"
        "  ...: View;\n"
        "  open func callInstance(value: int): int { return self.draw(value); }\n"
        "  open func callSource(value: int): int { return View.draw(self, value); }\n"
        "  open static func callStatic(value: int): int { return View.draw(Button(), value); }\n"
        "}\n"
        "type Bound: Widget { ...: View = View(); }\n"
        "type Inferred: Widget { ... = View(); }\n"
        "type Middle: Widget { ...: View; }\n"
        "type Leaf: Widget { ...: Middle; }\n"
        "type Override: Widget {\n"
        "  ...: View;\n"
        "  @mixable seal static func draw(target: Widget, value: int): int {\n"
        "    return View.draw(target, value) + 10;\n"
        "  }\n"
        "}\n";
    FengProgram *program = parse_program_or_die("mixable_seal.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *view;
    const FengDecl *button;
    const FengDecl *bound;
    const FengDecl *inferred;
    const FengDecl *middle;
    const FengDecl *leaf;
    const FengDecl *override;
    const FengTypeMember *view_static;
    const FengTypeMember *view_instance;
    const FengTypeMember *button_static;
    const FengTypeMember *button_instance;
    const FengTypeMember *middle_static;
    const FengTypeMember *leaf_static;
    const FengTypeMember *override_static;
    const FengTypeMember *override_instance;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    view = find_type_decl_by_name(analysis, "View");
    button = find_type_decl_by_name(analysis, "Button");
    bound = find_type_decl_by_name(analysis, "Bound");
    inferred = find_type_decl_by_name(analysis, "Inferred");
    middle = find_type_decl_by_name(analysis, "Middle");
    leaf = find_type_decl_by_name(analysis, "Leaf");
    override = find_type_decl_by_name(analysis, "Override");
    ASSERT(view != NULL && button != NULL && bound != NULL && inferred != NULL);
    ASSERT(middle != NULL && leaf != NULL && override != NULL);

    view_static = find_type_method_named(view, "draw", true);
    view_instance = find_type_method_named(view, "draw", false);
    button_static = find_type_method_named(button, "draw", true);
    button_instance = find_type_method_named(button, "draw", false);
    middle_static = find_type_method_named(middle, "draw", true);
    leaf_static = find_type_method_named(leaf, "draw", true);
    override_static = find_type_method_named(override, "draw", true);
    override_instance = find_type_method_named(override, "draw", false);
    ASSERT(view_static != NULL && view_instance != NULL);
    ASSERT(button_static != NULL && button_instance != NULL);
    ASSERT(middle_static != NULL && leaf_static != NULL);
    ASSERT(override_static != NULL && override_instance != NULL);

    ASSERT(view_static->visibility == FENG_VISIBILITY_PRIVATE);
    ASSERT(view_static->is_mixable && !view_static->is_mixin_static_wrapper);
    ASSERT(view_instance->visibility == FENG_VISIBILITY_PRIVATE);
    ASSERT(!view_instance->is_mixable && view_instance->is_mixin_instance_wrapper);
    ASSERT(button_static->visibility == FENG_VISIBILITY_PRIVATE);
    ASSERT(button_static->is_mixable && button_static->is_mixin_static_wrapper);
    ASSERT(button_instance->visibility == FENG_VISIBILITY_PRIVATE);
    ASSERT(!button_instance->is_mixable && button_instance->is_mixin_instance_wrapper);
    ASSERT(button_static->mixin_source_member == view_static);
    ASSERT(button_instance->mixin_source_member == button_static);
    ASSERT(middle_static->mixin_source_member == view_static);
    ASSERT(leaf_static->mixin_source_member == middle_static);
    ASSERT(override_static->visibility == FENG_VISIBILITY_PRIVATE);
    ASSERT(override_static->is_mixable && !override_static->is_mixin_static_wrapper);
    ASSERT(override_instance->visibility == FENG_VISIBILITY_PRIVATE);
    ASSERT(override_instance->mixin_source_member == override_static);

    ASSERT(feng_semantic_type_has_mixable_seal_access(
        button, view, view_static));
    ASSERT(feng_semantic_type_has_mixable_seal_access(
        bound, view, view_static));
    ASSERT(feng_semantic_type_has_mixable_seal_access(
        inferred, view, view_static));
    ASSERT(feng_semantic_type_has_mixable_seal_access(
        middle, view, view_static));
    ASSERT(feng_semantic_type_has_mixable_seal_access(
        leaf, middle, middle_static));
    ASSERT(!feng_semantic_type_has_mixable_seal_access(
        leaf, view, view_static));

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

