/* Each mixable declaration constraint reports its dedicated diagnostic code. */
static void test_mixable_contract_diagnostics_are_stable(void) {
    const char *sources[] = {
        "module demo.m0; spec W {} type V: W { @mixable(1) static func f(w: W) {} }",
        "module demo.m1; spec W {} type V: W { @mixable func f(w: W) {} }",
        "module demo.m2; spec W {} type V: W { @mixable static func f() {} }",
        "module demo.m3; spec W {} type V: W { @mixable static func f(w: W...) {} }",
        "module demo.m4; type V { @mixable static func f(value: int) {} }",
        "module demo.m5; spec W {} type V { @mixable static func f(w: W) {} }",
        "module demo.m6; spec W {} type V: W { @mixable open static func f(w: W) {} } type T { ...: V; }"
    };
    const char *codes[] = {
        "AE1329", "AE1330", "AE1331", "AE1332", "AE1333", "AE1334", "AE1335"
    };

    for (size_t index = 0U; index < 7U; ++index) {
        FengProgram *program = parse_program_or_die("mixable_bad.ff", sources[index]);
        const FengProgram *programs[] = {program};
        FengSemanticAnalysis *analysis = NULL;
        FengSemanticError *errors = NULL;
        size_t error_count = 0U;

        ASSERT(!feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                      &analysis, &errors, &error_count));
        ASSERT(error_count >= 1U);
        ASSERT(strcmp(errors[0].code, codes[index]) == 0);
        feng_semantic_errors_free(errors, error_count);
        feng_program_free(program);
    }
}

/* Field support adds exactly one annotation shape: an argument-free,
 * explicitly seal, non-static instance field owned by a concrete type. */
static void test_mixable_seal_field_contract_diagnostics_are_stable(void) {
    const char *sources[] = {
        "module demo.mf0; type V { @mixable(1) seal var value: int; }",
        "module demo.mf1; type V { @mixable var value: int; }",
        "module demo.mf2; type V { @mixable open let value: int = 1; }",
        "module demo.mf3; type V { @mixable seal static var value: int = 1; }",
        "module demo.mf4; spec S { @mixable seal var value: int; }",
        "module demo.mf5; type V { @mixable func V() {} }",
        "module demo.mf6; type V { @mixable func ~V() {} }"
    };
    const char *codes[] = {
        "AE1329", "AE1330", "AE1330", "AE1330",
        "AE1330", "AE1330", "AE1330"
    };

    for (size_t index = 0U;
         index < sizeof(sources) / sizeof(sources[0]);
         ++index) {
        FengProgram *program = parse_program_or_die(
            "mixable_seal_field_bad.ff", sources[index]);
        const FengProgram *programs[] = {program};
        FengSemanticAnalysis *analysis = NULL;
        FengSemanticError *errors = NULL;
        size_t error_count = 0U;

        ASSERT(!feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                      &analysis, &errors, &error_count));
        ASSERT(error_count >= 1U);
        ASSERT(strcmp(errors[0].code, codes[index]) == 0);
        feng_semantic_errors_free(errors, error_count);
        feng_program_free(program);
    }
}

/* Return whether a named type ref ends in the requested source-level name. */
static bool spec_upcast_type_ref_leaf_is(const FengTypeRef *type_ref,
                                         const char *name) {
    const FengSlice *leaf;
    size_t name_length;

    if (type_ref == NULL || name == NULL ||
        type_ref->kind != FENG_TYPE_REF_NAMED ||
        type_ref->as.named.segment_count == 0U) {
        return false;
    }
    leaf = &type_ref->as.named.segments[type_ref->as.named.segment_count - 1U];
    name_length = strlen(name);
    return leaf->length == name_length &&
           memcmp(leaf->data, name, name_length) == 0;
}

/* Explicit generic function and method targets use the surrounding callable
 * spec as a target context, including when that context is an explicit cast. */
static void test_explicit_generic_callable_values_and_unbound_casts(void) {
    const char *source =
        "module demo.callable.explicit_target;\n"
        "spec IntMapper(value: int): int;\n"
        "func identity<T>(value: T): T { return value; }\n"
        "func plusOne(value: int): int { return value + 1; }\n"
        "type Reader {\n"
        "    func identity<T>(value: T): T { return value; }\n"
        "    func plusOne(value: int): int { return value + 1; }\n"
        "}\n"
        "func accept(mapper: IntMapper): int { return mapper(10); }\n"
        "func makeTop(): IntMapper { return identity<int>; }\n"
        "func exercise(reader: Reader): int {\n"
        "    let top: IntMapper = identity<int>;\n"
        "    let method: IntMapper = reader.identity<int>;\n"
        "    let topCast = (IntMapper)identity<int>;\n"
        "    let methodCast = (IntMapper)reader.identity<int>;\n"
        "    let plainTop = (IntMapper)plusOne;\n"
        "    let plainMethod = (IntMapper)reader.plusOne;\n"
        "    return top(1) + method(2) + topCast(3) + methodCast(4) +\n"
        "           plainTop(5) + plainMethod(6) + accept(identity<int>);\n"
        "}\n";
    FengProgram *program = parse_program_or_die(
        "explicit_generic_callable_value_ok.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *exercise;
    const FengDecl *make_top;
    const FengExpr *expressions[6];
    const FengSpecCoercionSite *site;
    const char *int_canonical = sizeof(void *) >= 8U ? "i64" : "i32";

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    exercise = find_function_decl_in_program(program, "exercise");
    make_top = find_function_decl_in_program(program, "makeTop");
    ASSERT(exercise != NULL && make_top != NULL);
    for (size_t index = 0U; index < 6U; ++index) {
        expressions[index] = nth_let_initializer(
            &exercise->as.function_decl, index);
        ASSERT(expressions[index] != NULL);
    }

    /* Direct top-level and bound instance generic targets retain their
     * explicit callable-local argument in the semantic sidecar. */
    site = feng_semantic_lookup_spec_coercion_site(analysis, expressions[0]);
    ASSERT(site != NULL);
    ASSERT(site->form == FENG_SPEC_COERCION_FORM_CALLABLE);
    ASSERT(site->callable_source ==
           FENG_SPEC_COERCION_CALLABLE_SOURCE_TOP_LEVEL_FN);
    ASSERT(site->callable_decl != NULL);
    ASSERT(site->callable_member == NULL);
    ASSERT(site->callable_type_arg_count == 1U);
    ASSERT(spec_upcast_type_ref_leaf_is(site->callable_type_args[0],
                                        int_canonical));
    ASSERT(spec_upcast_type_ref_leaf_is(site->target_spec_type_ref,
                                        "IntMapper"));

    site = feng_semantic_lookup_spec_coercion_site(analysis, expressions[1]);
    ASSERT(site != NULL);
    ASSERT(site->callable_source ==
           FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE);
    ASSERT(site->callable_decl == NULL);
    ASSERT(site->callable_member != NULL);
    ASSERT(site->callable_type_arg_count == 1U);
    ASSERT(spec_upcast_type_ref_leaf_is(site->callable_type_args[0],
                                        int_canonical));
    ASSERT(spec_upcast_type_ref_leaf_is(site->callable_receiver_type_ref,
                                        "Reader"));

    /* A cast records the same source expression and does not create an
     * already-bound intermediary callable value. */
    ASSERT(expressions[2]->kind == FENG_EXPR_CAST);
    site = feng_semantic_lookup_spec_coercion_site(
        analysis, expressions[2]->as.cast.value);
    ASSERT(site != NULL);
    ASSERT(site->callable_source ==
           FENG_SPEC_COERCION_CALLABLE_SOURCE_TOP_LEVEL_FN);
    ASSERT(site->callable_type_arg_count == 1U);
    ASSERT(expressions[3]->kind == FENG_EXPR_CAST);
    site = feng_semantic_lookup_spec_coercion_site(
        analysis, expressions[3]->as.cast.value);
    ASSERT(site != NULL);
    ASSERT(site->callable_source ==
           FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE);
    ASSERT(site->callable_type_arg_count == 1U);

    /* The same explicit target context also accepts ordinary unbound,
     * non-generic top-level and instance method references. */
    ASSERT(expressions[4]->kind == FENG_EXPR_CAST);
    site = feng_semantic_lookup_spec_coercion_site(
        analysis, expressions[4]->as.cast.value);
    ASSERT(site != NULL);
    ASSERT(site->callable_source ==
           FENG_SPEC_COERCION_CALLABLE_SOURCE_TOP_LEVEL_FN);
    ASSERT(site->callable_type_arg_count == 0U);
    ASSERT(expressions[5]->kind == FENG_EXPR_CAST);
    site = feng_semantic_lookup_spec_coercion_site(
        analysis, expressions[5]->as.cast.value);
    ASSERT(site != NULL);
    ASSERT(site->callable_source ==
           FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE);
    ASSERT(site->callable_type_arg_count == 0U);

    /* Return and argument target contexts consume the same explicit target
     * without leaving a polymorphic callable value behind. */
    ASSERT(make_top->as.function_decl.body->statement_count == 1U);
    ASSERT(make_top->as.function_decl.body->statements[0]->kind ==
           FENG_STMT_RETURN);
    site = feng_semantic_lookup_spec_coercion_site(
        analysis,
        make_top->as.function_decl.body->statements[0]->as.return_value);
    ASSERT(site != NULL);
    ASSERT(site->callable_type_arg_count == 1U);

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Object-form spec method values use the same target-driven member selection
 * as concrete method values while retaining the exact declaring requirement
 * and receiver spec instance in the callable-coercion sidecar. */
static void test_object_spec_method_values_record_exact_target_context(void) {
    const char *source =
        "module demo.spec_method_value.target_context;\n"
        "spec Readable { func read(offset: int): string; }\n"
        "spec ChildReadable: Readable {}\n"
        "spec LeftReadable { func read(offset: int): string; }\n"
        "spec RightReadable { func read(offset: int): string; }\n"
        "spec CombinedReadable: LeftReadable, RightReadable {}\n"
        "spec Reader(offset: int): string;\n"
        "func accept(reader: Reader): Reader { return reader; }\n"
        "func make(value: Readable): Reader { return value.read; }\n"
        "func exercise(value: ChildReadable): Reader {\n"
        "    let bound: Reader = value.read;\n"
        "    let casted = (Reader)value.read;\n"
        "    return accept(value.read);\n"
        "}\n"
        "func bindCombined(value: CombinedReadable): Reader {\n"
        "    return value.read;\n"
        "}\n";
    FengProgram *program = parse_program_or_die(
        "object_spec_method_value_target_context.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *readable;
    const FengDecl *left_readable;
    const FengDecl *reader;
    const FengDecl *make;
    const FengDecl *exercise;
    const FengDecl *bind_combined;
    const FengTypeMember *read_member = NULL;
    const FengTypeMember *left_read_member = NULL;
    const FengExpr *sites[5];
    const FengSpecCoercionSite *site;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    readable = find_spec_decl_by_name(analysis, "Readable");
    left_readable = find_spec_decl_by_name(analysis, "LeftReadable");
    reader = find_spec_decl_by_name(analysis, "Reader");
    make = find_function_decl_in_program(program, "make");
    exercise = find_function_decl_in_program(program, "exercise");
    bind_combined = find_function_decl_in_program(program, "bindCombined");
    ASSERT(readable != NULL && left_readable != NULL && reader != NULL);
    ASSERT(make != NULL && exercise != NULL && bind_combined != NULL);
    for (size_t index = 0U;
         index < readable->as.spec_decl.as.object.member_count;
         ++index) {
        const FengTypeMember *member =
            readable->as.spec_decl.as.object.members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->as.callable.name.length == strlen("read") &&
            memcmp(member->as.callable.name.data, "read", strlen("read")) == 0) {
            read_member = member;
            break;
        }
    }
    for (size_t index = 0U;
         index < left_readable->as.spec_decl.as.object.member_count;
         ++index) {
        const FengTypeMember *member =
            left_readable->as.spec_decl.as.object.members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->as.callable.name.length == strlen("read") &&
            memcmp(member->as.callable.name.data, "read", strlen("read")) == 0) {
            left_read_member = member;
            break;
        }
    }
    ASSERT(read_member != NULL && left_read_member != NULL);

    sites[0] = nth_let_initializer(&exercise->as.function_decl, 0U);
    sites[1] = nth_let_initializer(&exercise->as.function_decl, 1U);
    ASSERT(sites[0] != NULL && sites[1] != NULL);
    ASSERT(sites[1]->kind == FENG_EXPR_CAST);
    sites[1] = sites[1]->as.cast.value;
    ASSERT(exercise->as.function_decl.body->statement_count == 3U);
    ASSERT(exercise->as.function_decl.body->statements[2]->kind ==
           FENG_STMT_RETURN);
    sites[2] = exercise->as.function_decl.body->statements[2]
                   ->as.return_value;
    ASSERT(sites[2] != NULL && sites[2]->kind == FENG_EXPR_CALL);
    ASSERT(sites[2]->as.call.arg_count == 1U);
    sites[2] = sites[2]->as.call.args[0];
    ASSERT(make->as.function_decl.body->statement_count == 1U);
    ASSERT(make->as.function_decl.body->statements[0]->kind == FENG_STMT_RETURN);
    sites[3] = make->as.function_decl.body->statements[0]->as.return_value;
    ASSERT(bind_combined->as.function_decl.body->statement_count == 1U);
    ASSERT(bind_combined->as.function_decl.body->statements[0]->kind ==
           FENG_STMT_RETURN);
    sites[4] = bind_combined->as.function_decl.body->statements[0]
                   ->as.return_value;

    for (size_t index = 0U; index < 4U; ++index) {
        site = feng_semantic_lookup_spec_coercion_site(analysis, sites[index]);
        ASSERT(site != NULL);
        ASSERT(site->form == FENG_SPEC_COERCION_FORM_CALLABLE);
        ASSERT(site->callable_source ==
               FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE);
        ASSERT(site->target_spec_decl == reader);
        ASSERT(site->callable_member == read_member);
        ASSERT(site->callable_owner_type_decl == readable);
        ASSERT(site->callable_fit_decl == NULL);
        ASSERT(site->callable_type_arg_count == 0U);
        ASSERT(spec_upcast_type_ref_leaf_is(
            site->callable_receiver_type_ref,
            index < 3U ? "ChildReadable" : "Readable"));
    }

    /* Identical requirements inherited from two parents remain one logical
     * callable source, matching the existing direct-call behavior. */
    site = feng_semantic_lookup_spec_coercion_site(analysis, sites[4]);
    ASSERT(site != NULL);
    ASSERT(site->callable_source ==
           FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE);
    ASSERT(site->target_spec_decl == reader);
    ASSERT(site->callable_member == left_read_member);
    ASSERT(site->callable_owner_type_decl == left_readable);
    ASSERT(spec_upcast_type_ref_leaf_is(site->callable_receiver_type_ref,
                                        "CombinedReadable"));

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Intersection-form spec method values consume the same projected requirement
 * surface as direct calls. The sidecar keeps the complete intersection receiver
 * while naming the original object-form requirement selected from a direct,
 * inherited, nested, overloaded, or deduplicated member path. */
static void test_intersection_spec_method_values_record_merged_surface(void) {
    const char *source =
        "module demo.intersection_method_value.merged_surface;\n"
        "spec Root<T> { func inherited(value: T): T; }\n"
        "spec Left<T>: Root<T> { func select(value: T): T; }\n"
        "spec Right {\n"
        "  func select(value: string): string;\n"
        "  func right(value: int): int;\n"
        "}\n"
        "spec Pair<T>: Left<T> & Right;\n"
        "spec Extra { func extra(value: int): int; }\n"
        "spec Nested<T>: Pair<T> & Extra;\n"
        "spec SameLeft { func same(value: int): int; }\n"
        "spec SameRight { func same(value: int): int; }\n"
        "spec SameIntersection: SameLeft & SameRight;\n"
        "spec IntMapper(value: int): int;\n"
        "spec StringMapper(value: string): string;\n"
        "func accept(mapper: IntMapper): IntMapper { return mapper; }\n"
        "func exercise(value: Nested<int>): IntMapper {\n"
        "  let selected: IntMapper = value.select;\n"
        "  let inherited: IntMapper = value.inherited;\n"
        "  let extra = (IntMapper)value.extra;\n"
        "  return accept(value.right);\n"
        "}\n"
        "func selectString(value: Nested<int>): StringMapper {\n"
        "  return value.select;\n"
        "}\n"
        "func bindSame(value: SameIntersection): IntMapper {\n"
        "  return value.same;\n"
        "}\n";
    FengProgram *program = parse_program_or_die(
        "intersection_spec_method_value_merged_surface.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *exercise;
    const FengDecl *select_string;
    const FengDecl *bind_same;
    const FengDecl *expected_owners[6];
    const FengDecl *expected_targets[6];
    const char *expected_receivers[6] = {
        "Nested", "Nested", "Nested", "Nested", "Nested",
        "SameIntersection"
    };
    const FengExpr *sites[6];

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    exercise = find_function_decl_in_program(program, "exercise");
    select_string = find_function_decl_in_program(program, "selectString");
    bind_same = find_function_decl_in_program(program, "bindSame");
    ASSERT(exercise != NULL && select_string != NULL && bind_same != NULL);

    expected_owners[0] = find_spec_decl_by_name(analysis, "Left");
    expected_owners[1] = find_spec_decl_by_name(analysis, "Root");
    expected_owners[2] = find_spec_decl_by_name(analysis, "Extra");
    expected_owners[3] = find_spec_decl_by_name(analysis, "Right");
    expected_owners[4] = find_spec_decl_by_name(analysis, "Right");
    expected_owners[5] = find_spec_decl_by_name(analysis, "SameLeft");
    for (size_t index = 0U; index < 6U; ++index) {
        ASSERT(expected_owners[index] != NULL);
        expected_targets[index] = find_spec_decl_by_name(
            analysis, index == 4U ? "StringMapper" : "IntMapper");
        ASSERT(expected_targets[index] != NULL);
    }

    sites[0] = nth_let_initializer(&exercise->as.function_decl, 0U);
    sites[1] = nth_let_initializer(&exercise->as.function_decl, 1U);
    sites[2] = nth_let_initializer(&exercise->as.function_decl, 2U);
    ASSERT(sites[0] != NULL && sites[1] != NULL && sites[2] != NULL);
    ASSERT(sites[2]->kind == FENG_EXPR_CAST);
    sites[2] = sites[2]->as.cast.value;
    ASSERT(exercise->as.function_decl.body->statement_count == 4U);
    ASSERT(exercise->as.function_decl.body->statements[3]->kind ==
           FENG_STMT_RETURN);
    sites[3] = exercise->as.function_decl.body->statements[3]
                   ->as.return_value;
    ASSERT(sites[3] != NULL && sites[3]->kind == FENG_EXPR_CALL);
    ASSERT(sites[3]->as.call.arg_count == 1U);
    sites[3] = sites[3]->as.call.args[0];
    ASSERT(select_string->as.function_decl.body->statement_count == 1U);
    sites[4] = select_string->as.function_decl.body->statements[0]
                   ->as.return_value;
    ASSERT(bind_same->as.function_decl.body->statement_count == 1U);
    sites[5] = bind_same->as.function_decl.body->statements[0]
                   ->as.return_value;

    for (size_t index = 0U; index < 6U; ++index) {
        const FengSpecCoercionSite *site =
            feng_semantic_lookup_spec_coercion_site(analysis, sites[index]);

        ASSERT(site != NULL);
        ASSERT(site->form == FENG_SPEC_COERCION_FORM_CALLABLE);
        ASSERT(site->callable_source ==
               FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE);
        ASSERT(site->target_spec_decl == expected_targets[index]);
        ASSERT(site->callable_member != NULL);
        ASSERT(site->callable_owner_type_decl == expected_owners[index]);
        ASSERT(site->callable_fit_decl == NULL);
        ASSERT(site->callable_type_arg_count == 0U);
        ASSERT(spec_upcast_type_ref_leaf_is(
            site->callable_receiver_type_ref, expected_receivers[index]));
    }

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* A method value formed from T: ObjectSpec keeps T as the receiver type while
 * selecting the exact constraint requirement and callable target at compile
 * time. All target-bearing expression positions share one reifiable callable
 * dependency in the generic body. */
static void test_constrained_generic_spec_method_values_preserve_receiver(void) {
    const char *source =
        "module demo.spec_method_value.generic_receiver;\n"
        "spec Readable { func read(offset: int): string; }\n"
        "spec Reader(offset: int): string;\n"
        "func accept(reader: Reader): Reader { return reader; }\n"
        "func exercise<T: Readable>(value: T): Reader {\n"
        "    let bound: Reader = value.read;\n"
        "    let casted = (Reader)value.read;\n"
        "    return accept(value.read);\n"
        "}\n"
        "func returned<T: Readable>(value: T): Reader {\n"
        "    return value.read;\n"
        "}\n";
    FengProgram *program = parse_program_or_die(
        "constrained_generic_spec_method_value.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *readable;
    const FengDecl *reader;
    const FengDecl *exercise;
    const FengDecl *returned;
    const FengTypeMember *read_member = NULL;
    const FengExpr *sites[4];

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    readable = find_spec_decl_by_name(analysis, "Readable");
    reader = find_spec_decl_by_name(analysis, "Reader");
    exercise = find_function_decl_in_program(program, "exercise");
    returned = find_function_decl_in_program(program, "returned");
    ASSERT(readable != NULL && reader != NULL);
    ASSERT(exercise != NULL && returned != NULL);
    for (size_t index = 0U;
         index < readable->as.spec_decl.as.object.member_count;
         ++index) {
        const FengTypeMember *member =
            readable->as.spec_decl.as.object.members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->as.callable.name.length == strlen("read") &&
            memcmp(member->as.callable.name.data,
                   "read",
                   strlen("read")) == 0) {
            read_member = member;
            break;
        }
    }
    ASSERT(read_member != NULL);

    sites[0] = nth_let_initializer(&exercise->as.function_decl, 0U);
    sites[1] = nth_let_initializer(&exercise->as.function_decl, 1U);
    ASSERT(sites[0] != NULL && sites[1] != NULL);
    ASSERT(sites[1]->kind == FENG_EXPR_CAST);
    sites[1] = sites[1]->as.cast.value;
    ASSERT(exercise->as.function_decl.body->statement_count == 3U);
    ASSERT(exercise->as.function_decl.body->statements[2]->kind ==
           FENG_STMT_RETURN);
    sites[2] = exercise->as.function_decl.body->statements[2]
                   ->as.return_value;
    ASSERT(sites[2] != NULL && sites[2]->kind == FENG_EXPR_CALL);
    ASSERT(sites[2]->as.call.arg_count == 1U);
    sites[2] = sites[2]->as.call.args[0];
    ASSERT(returned->as.function_decl.body->statement_count == 1U);
    ASSERT(returned->as.function_decl.body->statements[0]->kind ==
           FENG_STMT_RETURN);
    sites[3] = returned->as.function_decl.body->statements[0]
                   ->as.return_value;

    for (size_t index = 0U; index < 4U; ++index) {
        const FengSpecCoercionSite *site =
            feng_semantic_lookup_spec_coercion_site(analysis, sites[index]);

        ASSERT(site != NULL);
        ASSERT(site->form == FENG_SPEC_COERCION_FORM_CALLABLE);
        ASSERT(site->callable_source ==
               FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE);
        ASSERT(site->target_spec_decl == reader);
        ASSERT(site->callable_member == read_member);
        ASSERT(site->callable_owner_type_decl == readable);
        ASSERT(site->callable_fit_decl == NULL);
        ASSERT(site->callable_type_arg_count == 0U);
        ASSERT(spec_upcast_type_ref_leaf_is(
            site->callable_receiver_type_ref, "T"));
    }

    {
        const FengReifiableDepSet *dep_set =
            feng_semantic_lookup_reifiable_dep_set(analysis, exercise);
        const FengReifiableCallableDep *dependency;

        ASSERT(dep_set != NULL);
        ASSERT(dep_set->callable_dep_count == 1U);
        dependency = &dep_set->callable_deps[0];
        ASSERT(dependency->purpose ==
               FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE);
        ASSERT(dependency->kind == FENG_RESOLVED_CALLABLE_SPEC_METHOD);
        ASSERT(dependency->owner_type_decl == readable);
        ASSERT(dependency->member == read_member);
        ASSERT(dependency->fit_decl == NULL);
        ASSERT(spec_upcast_type_ref_leaf_is(
            dependency->owner_instance_type_ref, "T"));
        ASSERT(spec_upcast_type_ref_leaf_is(
            dependency->target_callable_type_ref, "Reader"));
    }

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Find one instance method declared directly on an object-form spec. */
static const FengTypeMember *find_object_spec_method_named(
    const FengDecl *spec_decl,
    const char *name) {
    size_t name_length = strlen(name);

    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return NULL;
    }
    for (size_t index = 0U;
         index < spec_decl->as.spec_decl.as.object.member_count;
         ++index) {
        const FengTypeMember *member =
            spec_decl->as.spec_decl.as.object.members[index];

        if (member != NULL && !member->is_static &&
            member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->as.callable.name.length == name_length &&
            memcmp(member->as.callable.name.data,
                   name,
                   name_length) == 0) {
            return member;
        }
    }
    return NULL;
}

/* Find one declaration-ordered static method overload on an object spec. */
static const FengTypeMember *find_object_spec_static_method_named_at(
    const FengDecl *spec_decl,
    const char *name,
    size_t wanted_ordinal) {
    size_t name_length = strlen(name);
    size_t ordinal = 0U;

    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return NULL;
    }
    for (size_t index = 0U;
         index < spec_decl->as.spec_decl.as.object.member_count;
         ++index) {
        const FengTypeMember *member =
            spec_decl->as.spec_decl.as.object.members[index];

        if (member == NULL || !member->is_static ||
            member->kind != FENG_TYPE_MEMBER_METHOD ||
            member->as.callable.name.length != name_length ||
            memcmp(member->as.callable.name.data, name, name_length) != 0) {
            continue;
        }
        if (ordinal == wanted_ordinal) {
            return member;
        }
        ++ordinal;
    }
    return NULL;
}

/* A T: IntersectionSpec method value keeps T as the receiver while retaining
 * the complete merged constraint surface and exact leaf requirement. Direct,
 * parent, nested, overloaded, cast, argument and return targets all use the
 * same callable sidecar and dependency mechanism as MV02/MV05. */
static void test_constrained_generic_intersection_method_values_record_surface(void) {
    const char *source =
        "module demo.intersection_method_value.generic_receiver;\n"
        "spec Base { func inherited(value: int): int; }\n"
        "spec Left: Base {\n"
        "  func read(value: int): int;\n"
        "  func select(value: int): int;\n"
        "}\n"
        "spec Right {\n"
        "  func trace(value: int): int;\n"
        "  func select(value: string): string;\n"
        "}\n"
        "spec Pair: Left & Right;\n"
        "spec Extra { func extra(value: int): int; }\n"
        "spec Nested: Pair & Extra;\n"
        "spec IntMapper(value: int): int;\n"
        "spec StringMapper(value: string): string;\n"
        "func accept(mapper: IntMapper): IntMapper { return mapper; }\n"
        "func exercise<T: Nested>(value: T): IntMapper {\n"
        "  let read: IntMapper = value.read;\n"
        "  let inherited: IntMapper = value.inherited;\n"
        "  let extra = (IntMapper)value.extra;\n"
        "  let integer: IntMapper = value.select;\n"
        "  let text: StringMapper = value.select;\n"
        "  return accept(value.trace);\n"
        "}\n";
    FengProgram *program = parse_program_or_die(
        "constrained_generic_intersection_method_value.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *base;
    const FengDecl *left;
    const FengDecl *right;
    const FengDecl *extra;
    const FengDecl *nested;
    const FengDecl *int_mapper;
    const FengDecl *string_mapper;
    const FengDecl *exercise;
    const FengTypeMember *expected_members[6];
    const FengDecl *expected_targets[6];
    const FengExpr *sites[6];

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    base = find_spec_decl_by_name(analysis, "Base");
    left = find_spec_decl_by_name(analysis, "Left");
    right = find_spec_decl_by_name(analysis, "Right");
    extra = find_spec_decl_by_name(analysis, "Extra");
    nested = find_spec_decl_by_name(analysis, "Nested");
    int_mapper = find_spec_decl_by_name(analysis, "IntMapper");
    string_mapper = find_spec_decl_by_name(analysis, "StringMapper");
    exercise = find_function_decl_in_program(program, "exercise");
    ASSERT(base != NULL && left != NULL && right != NULL && extra != NULL);
    ASSERT(nested != NULL && int_mapper != NULL && string_mapper != NULL);
    ASSERT(exercise != NULL);

    expected_members[0] = find_object_spec_method_named(left, "read");
    expected_members[1] = find_object_spec_method_named(base, "inherited");
    expected_members[2] = find_object_spec_method_named(extra, "extra");
    expected_members[3] = find_object_spec_method_named(left, "select");
    expected_members[4] = find_object_spec_method_named(right, "select");
    expected_members[5] = find_object_spec_method_named(right, "trace");
    for (size_t index = 0U; index < 6U; ++index) {
        ASSERT(expected_members[index] != NULL);
        expected_targets[index] = index == 4U
                                      ? string_mapper
                                      : int_mapper;
    }

    for (size_t index = 0U; index < 5U; ++index) {
        sites[index] = nth_let_initializer(
            &exercise->as.function_decl, index);
        ASSERT(sites[index] != NULL);
    }
    ASSERT(sites[2]->kind == FENG_EXPR_CAST);
    sites[2] = sites[2]->as.cast.value;
    ASSERT(exercise->as.function_decl.body->statement_count == 6U);
    ASSERT(exercise->as.function_decl.body->statements[5]->kind ==
           FENG_STMT_RETURN);
    sites[5] = exercise->as.function_decl.body->statements[5]
                   ->as.return_value;
    ASSERT(sites[5] != NULL && sites[5]->kind == FENG_EXPR_CALL);
    ASSERT(sites[5]->as.call.arg_count == 1U);
    sites[5] = sites[5]->as.call.args[0];

    for (size_t index = 0U; index < 6U; ++index) {
        const FengSpecCoercionSite *site =
            feng_semantic_lookup_spec_coercion_site(
                analysis, sites[index]);

        ASSERT(site != NULL);
        ASSERT(site->form == FENG_SPEC_COERCION_FORM_CALLABLE);
        ASSERT(site->callable_source ==
               FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE);
        ASSERT(site->target_spec_decl == expected_targets[index]);
        ASSERT(site->callable_member == expected_members[index]);
        ASSERT(site->callable_owner_type_decl == nested);
        ASSERT(site->callable_fit_decl == NULL);
        ASSERT(site->callable_type_arg_count == 0U);
        ASSERT(spec_upcast_type_ref_leaf_is(
            site->callable_receiver_type_ref, "T"));
    }

    {
        const FengReifiableDepSet *dep_set =
            feng_semantic_lookup_reifiable_dep_set(analysis, exercise);

        ASSERT(dep_set != NULL);
        ASSERT(dep_set->callable_dep_count == 6U);
        for (size_t index = 0U;
             index < dep_set->callable_dep_count;
             ++index) {
            const FengReifiableCallableDep *dependency =
                &dep_set->callable_deps[index];

            ASSERT(dependency->purpose ==
                   FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE);
            ASSERT(dependency->kind == FENG_RESOLVED_CALLABLE_SPEC_METHOD);
            ASSERT(dependency->owner_type_decl == nested);
            ASSERT(dependency->fit_decl == NULL);
            ASSERT(spec_upcast_type_ref_leaf_is(
                dependency->owner_instance_type_ref, "T"));
        }
    }

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

