/* Intersection-constrained generic method values retain the callable target
 * and seal diagnostics. The no-target matrix also locks ISSUE-021 for both
 * object-form and intersection-form constraints. */
static void test_constrained_generic_intersection_method_values_reject_invalid_sources(void) {
    static const struct {
        const char *path;
        const char *source;
        const char *expected_code;
    } cases[] = {
        {
            "constrained_generic_object_method_value_without_target.ff",
            "module demo.generic_object_method_value.no_target;\n"
            "spec Readable { func read(value: int): int; }\n"
            "func bad<T: Readable>(value: T): void {\n"
            "  let reader = value.read;\n"
            "}\n",
            "AE0523"
        },
        {
            "constrained_generic_intersection_method_value_without_target.ff",
            "module demo.generic_intersection_method_value.no_target;\n"
            "spec Left { func read(value: int): int; }\n"
            "spec Right { func trace(): int; }\n"
            "spec Both: Left & Right;\n"
            "func bad<T: Both>(value: T): void {\n"
            "  let reader = value.read;\n"
            "}\n",
            "AE0523"
        },
        {
            "constrained_generic_intersection_method_value_mismatch.ff",
            "module demo.generic_intersection_method_value.mismatch;\n"
            "spec Left { func read(value: int): int; }\n"
            "spec Right { func trace(): int; }\n"
            "spec Both: Left & Right;\n"
            "spec Wrong(flag: bool): int;\n"
            "func bad<T: Both>(value: T): Wrong { return value.read; }\n",
            "AE0522"
        },
        {
            "constrained_generic_intersection_method_value_seal.ff",
            "module demo.generic_intersection_method_value.seal_access;\n"
            "spec Hidden { seal func secret(value: int): int; }\n"
            "spec Visible { func visible(): int; }\n"
            "spec Both: Hidden & Visible;\n"
            "spec Mapper(value: int): int;\n"
            "func bad<T: Both>(value: T): Mapper { return value.secret; }\n",
            "AE0708"
        }
    };

    for (size_t case_index = 0U;
         case_index < sizeof(cases) / sizeof(cases[0]);
         ++case_index) {
        FengProgram *program = parse_program_or_die(
            cases[case_index].path, cases[case_index].source);
        const FengProgram *programs[] = {program};
        FengSemanticAnalysis *analysis = NULL;
        FengSemanticError *errors = NULL;
        size_t error_count = 0U;

        ASSERT(!feng_semantic_analyze(programs, 1U,
                                      FENG_COMPILE_TARGET_LIB,
                                      &analysis,
                                      &errors,
                                      &error_count));
        ASSERT(semantic_error_code_count(
                   errors,
                   error_count,
                   cases[case_index].expected_code) > 0U);
        feng_semantic_errors_free(errors, error_count);
        feng_semantic_analysis_free(analysis);
        feng_program_free(program);
    }
}

/* Closing an intersection-constrained method value over an array must retain
 * the fit-owned array subject key in every leaf witness. This keeps witness
 * lookup valid after the generic-call resolver releases its temporary types. */
static void test_constrained_generic_intersection_array_witness_key_is_stable(void) {
    const char *source =
        "module demo.intersection_method_value.array_witness_key;\n"
        "spec Stateful { func step(delta: i32): i32; }\n"
        "spec Named { func name(): string; }\n"
        "spec Both: Stateful & Named;\n"
        "spec Mapper(delta: i32): i32;\n"
        "fit i32[]: Stateful, Named {\n"
        "  func step(delta: i32): i32 { return self[0] + delta; }\n"
        "  func name(): string { return \"array\"; }\n"
        "}\n"
        "func bind<T: Both>(value: T): Mapper { return value.step; }\n"
        "func run(value: i32[]): Mapper { return bind<i32[]>(value); }\n";
    FengProgram *program = parse_program_or_die(
        "constrained_generic_intersection_array_witness_key.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *stateful;
    const FengDecl *named;
    const FengDecl *fit;
    FengSemanticSubjectKey subject_key;
    const FengSpecWitness *stateful_witness;
    const FengSpecWitness *named_witness;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    stateful = find_spec_decl_by_name(analysis, "Stateful");
    named = find_spec_decl_by_name(analysis, "Named");
    fit = program->declarations[4];
    ASSERT(stateful != NULL && named != NULL);
    ASSERT(fit != NULL && fit->kind == FENG_DECL_FIT);
    ASSERT(fit->as.fit_decl.target != NULL);
    ASSERT(fit->as.fit_decl.target->kind == FENG_TYPE_REF_ARRAY);
    ASSERT(feng_semantic_subject_key_init_array_from_type_ref(
        &subject_key, fit->as.fit_decl.target));

    stateful_witness = feng_semantic_lookup_spec_witness(
        analysis, &subject_key, stateful);
    named_witness = feng_semantic_lookup_spec_witness(
        analysis, &subject_key, named);
    ASSERT(stateful_witness != NULL && named_witness != NULL);
    ASSERT(stateful_witness->subject_key.kind ==
           FENG_SEMANTIC_SUBJECT_KEY_ARRAY);
    ASSERT(named_witness->subject_key.kind ==
           FENG_SEMANTIC_SUBJECT_KEY_ARRAY);
    ASSERT(stateful_witness->subject_key.as.array.element_type_ref ==
           fit->as.fit_decl.target->as.inner);
    ASSERT(named_witness->subject_key.as.array.element_type_ref ==
           fit->as.fit_decl.target->as.inner);

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* IC01: direct static calls traverse the exact intersection/member-parent
 * surface, preserve the declaring requirement instance, select legal
 * overloads, and deduplicate semantically equivalent merged requirements.
 * The same resolver also restores the second object-form static overload. */
static void test_intersection_constrained_static_method_calls_record_surface(void) {
    const char *source =
        "module demo.intersection_static_call.surface;\n"
        "spec RootFactory<X> {\n"
        "  static func inherited(value: X): X;\n"
        "  static func duplicate(value: X): X;\n"
        "}\n"
        "spec Left<X>: RootFactory<X> {\n"
        "  static func choose(value: int): int;\n"
        "  static func duplicate(value: X): X;\n"
        "}\n"
        "spec Right<X> {\n"
        "  static func choose(value: string): string;\n"
        "  static func duplicate(value: X): X;\n"
        "}\n"
        "spec Pair<X>: Left<X> & Right<X>;\n"
        "spec Extra<X> { static func extra(value: X): X; }\n"
        "spec Nested<A, B>: Pair<B> & Extra<A>;\n"
        "spec ObjectOverloads {\n"
        "  static func select(value: int): int;\n"
        "  static func select(value: string): string;\n"
        "}\n"
        "func chooseInt<T: Nested<bool, int>>(value: int): int {\n"
        "  return T.choose(value);\n"
        "}\n"
        "func chooseText<T: Nested<bool, int>>(value: string): string {\n"
        "  return T.choose(value);\n"
        "}\n"
        "func inherited<T: Nested<bool, int>>(value: int): int {\n"
        "  return T.inherited(value);\n"
        "}\n"
        "func extra<T: Nested<bool, int>>(value: bool): bool {\n"
        "  return T.extra(value);\n"
        "}\n"
        "func duplicate<T: Nested<bool, int>>(value: int): int {\n"
        "  return T.duplicate(value);\n"
        "}\n"
        "func objectText<T: ObjectOverloads>(value: string): string {\n"
        "  return T.select(value);\n"
        "}\n";
    static const struct {
        const char *function_name;
        const char *owner_name;
        const char *member_name;
        size_t member_ordinal;
        const char *owner_arg_name;
    } cases[] = {
        {"chooseInt", "Left", "choose", 0U, NULL},
        {"chooseText", "Right", "choose", 0U, NULL},
        {"inherited", "RootFactory", "inherited", 0U, NULL},
        {"extra", "Extra", "extra", 0U, "bool"},
        {"duplicate", "Left", "duplicate", 0U, NULL},
        {"objectText", "ObjectOverloads", "select", 1U, NULL}
    };
    const char *int_canonical = sizeof(void *) >= 8U ? "i64" : "i32";
    FengProgram *program = parse_program_or_die(
        "intersection_constrained_static_method_call_surface.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    for (size_t index = 0U;
         index < sizeof(cases) / sizeof(cases[0]);
         ++index) {
        const FengDecl *function = find_function_decl_in_program(
            program, cases[index].function_name);
        const FengDecl *owner = find_spec_decl_by_name(
            analysis, cases[index].owner_name);
        const FengTypeMember *member =
            find_object_spec_static_method_named_at(
                owner,
                cases[index].member_name,
                cases[index].member_ordinal);
        const FengStmt *return_stmt;
        const FengExpr *call;
        const FengResolvedCallable *resolved;

        ASSERT(function != NULL && owner != NULL && member != NULL);
        ASSERT(function->as.function_decl.body != NULL);
        ASSERT(function->as.function_decl.body->statement_count == 1U);
        return_stmt = function->as.function_decl.body->statements[0];
        ASSERT(return_stmt != NULL && return_stmt->kind == FENG_STMT_RETURN);
        call = return_stmt->as.return_value;
        ASSERT(call != NULL && call->kind == FENG_EXPR_CALL);
        resolved = &call->as.call.resolved_callable;
        ASSERT(resolved->kind ==
               FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD);
        ASSERT(resolved->owner_type_decl == owner);
        ASSERT(resolved->member == member);
        ASSERT(spec_upcast_type_ref_leaf_is(
            resolved->owner_instance_type_ref, cases[index].owner_name));

        if (index < 5U) {
            const char *expected_arg = cases[index].owner_arg_name != NULL
                                           ? cases[index].owner_arg_name
                                           : int_canonical;

            ASSERT(resolved->owner_instance_type_ref->as.named.type_arg_count ==
                   1U);
            ASSERT(spec_upcast_type_ref_leaf_is(
                resolved->owner_instance_type_ref->as.named.type_args[0],
                expected_arg));
        } else {
            ASSERT(resolved->owner_instance_type_ref->as.named.type_arg_count ==
                   0U);
        }
    }

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* IC01 keeps access and overload diagnostics stable across an intersection
 * surface. A satisfying implementation type remains authorized to call a
 * seal static requirement from its own implementation context. */
static void test_intersection_constrained_static_method_call_diagnostics(void) {
    const char *authorized =
        "module demo.intersection_static_call.authorized;\n"
        "spec Hidden { seal static func secret(value: int): int; }\n"
        "spec Visible { static func visible(): int; }\n"
        "spec Both: Hidden & Visible;\n"
        "type Owner: Hidden, Visible {\n"
        "  seal static func secret(value: int): int { return value; }\n"
        "  static func visible(): int { return 1; }\n"
        "  static func call<T: Both>(value: int): int {\n"
        "    return T.secret(value);\n"
        "  }\n"
        "}\n";
    static const struct {
        const char *path;
        const char *source;
        const char *expected_code;
        size_t expected_count;
    } rejected[] = {
        {
            "intersection_static_call_seal.ff",
            "module demo.intersection_static_call.denied_seal;\n"
            "spec Hidden { seal static func secret(value: int): int; }\n"
            "spec Visible { static func visible(): int; }\n"
            "spec Both: Hidden & Visible;\n"
            "func bad<T: Both>(value: int): int {\n"
            "  return T.secret(value);\n"
            "}\n",
            "AE0708",
            1U
        },
        {
            "intersection_static_call_mismatch.ff",
            "module demo.intersection_static_call.mismatch;\n"
            "spec Left { static func choose(value: int): int; }\n"
            "spec Right { static func trace(): int; }\n"
            "spec Both: Left & Right;\n"
            "func bad<T: Both>(value: bool): int {\n"
            "  return T.choose(value);\n"
            "}\n",
            "AE0512",
            1U
        },
        {
            "intersection_static_call_missing.ff",
            "module demo.intersection_static_call.missing;\n"
            "spec Left { static func choose(value: int): int; }\n"
            "spec Right { static func trace(): int; }\n"
            "spec Both: Left & Right;\n"
            "func bad<T: Both>(): int { return T.unknown(); }\n",
            "AE0512",
            1U
        },
        {
            "intersection_static_call_ambiguous.ff",
            "module demo.intersection_static_call.ambiguous;\n"
            "spec LeftArg {}\n"
            "spec RightArg {}\n"
            "spec LeftFactory {\n"
            "  static func select(value: LeftArg): int;\n"
            "}\n"
            "spec RightFactory {\n"
            "  static func select(value: RightArg): int;\n"
            "}\n"
            "spec BothFactory: LeftFactory & RightFactory;\n"
            "type BothArg: LeftArg, RightArg {}\n"
            "func bad<T: BothFactory>(value: BothArg): int {\n"
            "  return T.select(value);\n"
            "}\n",
            "AE0511",
            1U
        }
    };

    assert_single_source_semantic_ok(
        "intersection_static_call_authorized.ff", authorized);
    for (size_t index = 0U;
         index < sizeof(rejected) / sizeof(rejected[0]);
         ++index) {
        FengProgram *program = parse_program_or_die(
            rejected[index].path, rejected[index].source);
        const FengProgram *programs[] = {program};
        FengSemanticAnalysis *analysis = NULL;
        FengSemanticError *errors = NULL;
        size_t error_count = 0U;

        ASSERT(!feng_semantic_analyze(programs, 1U,
                                      FENG_COMPILE_TARGET_LIB,
                                      &analysis,
                                      &errors,
                                      &error_count));
        ASSERT(semantic_error_code_count(
                   errors,
                   error_count,
                   rejected[index].expected_code) ==
               rejected[index].expected_count);
        feng_semantic_errors_free(errors, error_count);
        feng_semantic_analysis_free(analysis);
        feng_program_free(program);
    }
}

/* IC01 ISSUE-005: a non-generic child spec may close a generic parent with a
 * fixed argument. Both nominal declarations and fit declarations must verify
 * the inherited requirement against that exact parent instance. */
static void test_fixed_generic_parent_spec_satisfaction(void) {
    const char *source =
        "module demo.intersection_static_call.fixed_parent;\n"
        "spec RootFactory<T> {\n"
        "  static func inherited(value: T): T;\n"
        "}\n"
        "spec NumberFactory: RootFactory<i32> {}\n"
        "type Direct: NumberFactory {\n"
        "  static func inherited(value: i32): i32 { return value; }\n"
        "}\n"
        "type Fitted {}\n"
        "fit Fitted: NumberFactory {\n"
        "  static func inherited(value: i32): i32 { return value; }\n"
        "}\n";

    assert_single_source_semantic_ok(
        "fixed_generic_parent_spec_satisfaction.ff", source);
}

/* IC01 ISSUE-007: closing an intersection constraint materializes each
 * object-form leaf witness. Static requirements select static type members,
 * just as instance requirements select instance members. */
static void test_intersection_static_constraint_materializes_leaf_witnesses(void) {
    const char *source =
        "module demo.intersection_static_call.leaf_witness;\n"
        "spec Factory { static func create(seed: i32): i32; }\n"
        "spec Labeler { static func label(): string; }\n"
        "spec Both: Factory & Labeler;\n"
        "type Implementation: Factory, Labeler {\n"
        "  static func create(seed: i32): i32 { return seed + 1; }\n"
        "  static func label(): string { return \"implementation\"; }\n"
        "}\n"
        "func invoke<T: Both>(seed: i32): i32 { return T.create(seed); }\n"
        "func close(): i32 { return invoke<Implementation>(1); }\n";
    FengProgram *program = parse_program_or_die(
        "intersection_static_constraint_leaf_witness.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *implementation;
    const FengDecl *factory;
    const FengDecl *labeler;
    FengSemanticSubjectKey subject_key;
    const FengSpecWitness *factory_witness;
    const FengSpecWitness *labeler_witness;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    implementation = find_type_decl_by_name(analysis, "Implementation");
    factory = find_spec_decl_by_name(analysis, "Factory");
    labeler = find_spec_decl_by_name(analysis, "Labeler");
    ASSERT(implementation != NULL && factory != NULL && labeler != NULL);
    ASSERT(implementation->as.type_decl.member_count == 2U);
    subject_key = feng_semantic_subject_key_for_type_decl(implementation);
    factory_witness = feng_semantic_lookup_spec_witness(
        analysis, &subject_key, factory);
    labeler_witness = feng_semantic_lookup_spec_witness(
        analysis, &subject_key, labeler);
    ASSERT(factory_witness != NULL && factory_witness->member_count == 1U);
    ASSERT(labeler_witness != NULL && labeler_witness->member_count == 1U);
    ASSERT(factory_witness->members[0].impl_member ==
           implementation->as.type_decl.members[0]);
    ASSERT(labeler_witness->members[0].impl_member ==
           implementation->as.type_decl.members[1]);
    ASSERT(factory_witness->members[0].source_kind ==
           FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_METHOD);
    ASSERT(labeler_witness->members[0].source_kind ==
           FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_METHOD);

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* A concrete nominal element in an array fit is not a fit-local type
 * parameter. Its non-generic method therefore must not acquire a member-level
 * reifiable dependency set merely because the target has array shape. */
static void test_concrete_enum_array_fit_is_not_reifiable_generic(void) {
    const char *source =
        "module demo.fit_enum_array.reifiable_classification;\n"
        "enum Element { First }\n"
        "spec Readable { func read(): i32; }\n"
        "fit Element[!]: Readable {\n"
        "  func read(): i32 {\n"
        "    return if self[0] == Element.First { 1 } else { 0 };\n"
        "  }\n"
        "}\n"
        "func run(value: Element[!]): i32 { return value.read(); }\n";
    FengProgram *program = parse_program_or_die(
        "concrete_enum_array_fit_reifiable_classification.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *fit;
    const FengTypeMember *read;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    fit = program->declarations[2];
    ASSERT(fit != NULL && fit->kind == FENG_DECL_FIT);
    ASSERT(fit->as.fit_decl.member_count == 1U);
    read = fit->as.fit_decl.members[0];
    ASSERT(read != NULL && read->kind == FENG_TYPE_MEMBER_METHOD);
    ASSERT(feng_semantic_lookup_member_reifiable_dep_set(
               analysis, fit, read) == NULL);

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* A T: ObjectSpec static method value keeps T as the owner while selecting
 * the exact static requirement and callable target at compile time. Binding,
 * cast, argument and return targets share one callable-value dependency;
 * direct T.method() dispatch remains independent of that dependency path. */
static void test_constrained_generic_spec_static_method_values(void) {
    const char *source =
        "module demo.spec_static_method_value.generic_owner;\n"
        "spec Factory { static func create(seed: int): int; }\n"
        "spec Creator(seed: int): int;\n"
        "func accept(creator: Creator): Creator { return creator; }\n"
        "func exercise<T: Factory>(): Creator {\n"
        "    let bound: Creator = T.create;\n"
        "    let casted = (Creator)T.create;\n"
        "    return accept(T.create);\n"
        "}\n"
        "func returned<T: Factory>(): Creator { return T.create; }\n"
        "func direct<T: Factory>(seed: int): int { return T.create(seed); }\n"
        "spec GenericFactory<T> { static func map(value: T): T; }\n"
        "spec MappedFactory<Unused, Value>: GenericFactory<Value> {}\n"
        "spec IntMapper(value: int): int;\n"
        "func inherited<T: MappedFactory<string, int>>(): IntMapper {\n"
        "    return T.map;\n"
        "}\n"
        "spec SecretFactory {\n"
        "    @friend(Reader) seal static func secret(seed: int): int;\n"
        "}\n"
        "type Reader {\n"
        "    static func bindSecret<T: SecretFactory>(): Creator {\n"
        "        return T.secret;\n"
        "    }\n"
        "}\n";
    FengProgram *program = parse_program_or_die(
        "constrained_generic_spec_static_method_value.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *factory;
    const FengDecl *creator;
    const FengDecl *generic_factory;
    const FengDecl *int_mapper;
    const FengDecl *secret_factory;
    const FengDecl *exercise;
    const FengDecl *returned;
    const FengDecl *direct;
    const FengDecl *inherited;
    const FengDecl *reader;
    const FengTypeMember *create_member = NULL;
    const FengTypeMember *map_member = NULL;
    const FengTypeMember *secret_member = NULL;
    const FengTypeMember *bind_secret_member = NULL;
    const FengExpr *sites[4];

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    factory = find_spec_decl_by_name(analysis, "Factory");
    creator = find_spec_decl_by_name(analysis, "Creator");
    generic_factory = find_spec_decl_by_name(analysis, "GenericFactory");
    int_mapper = find_spec_decl_by_name(analysis, "IntMapper");
    secret_factory = find_spec_decl_by_name(analysis, "SecretFactory");
    exercise = find_function_decl_in_program(program, "exercise");
    returned = find_function_decl_in_program(program, "returned");
    direct = find_function_decl_in_program(program, "direct");
    inherited = find_function_decl_in_program(program, "inherited");
    reader = find_type_decl_by_name(analysis, "Reader");
    ASSERT(factory != NULL && creator != NULL && generic_factory != NULL);
    ASSERT(int_mapper != NULL && secret_factory != NULL);
    ASSERT(exercise != NULL && returned != NULL && direct != NULL);
    ASSERT(inherited != NULL && reader != NULL);

    for (size_t index = 0U;
         index < factory->as.spec_decl.as.object.member_count;
         ++index) {
        const FengTypeMember *member =
            factory->as.spec_decl.as.object.members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->as.callable.name.length == strlen("create") &&
            memcmp(member->as.callable.name.data,
                   "create",
                   strlen("create")) == 0) {
            create_member = member;
            break;
        }
    }
    for (size_t index = 0U;
         index < generic_factory->as.spec_decl.as.object.member_count;
         ++index) {
        const FengTypeMember *member =
            generic_factory->as.spec_decl.as.object.members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->as.callable.name.length == strlen("map") &&
            memcmp(member->as.callable.name.data,
                   "map",
                   strlen("map")) == 0) {
            map_member = member;
            break;
        }
    }
    for (size_t index = 0U;
         index < secret_factory->as.spec_decl.as.object.member_count;
         ++index) {
        const FengTypeMember *member =
            secret_factory->as.spec_decl.as.object.members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->as.callable.name.length == strlen("secret") &&
            memcmp(member->as.callable.name.data,
                   "secret",
                   strlen("secret")) == 0) {
            secret_member = member;
            break;
        }
    }
    for (size_t index = 0U;
         index < reader->as.type_decl.member_count;
         ++index) {
        const FengTypeMember *member = reader->as.type_decl.members[index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->as.callable.name.length == strlen("bindSecret") &&
            memcmp(member->as.callable.name.data,
                   "bindSecret",
                   strlen("bindSecret")) == 0) {
            bind_secret_member = member;
            break;
        }
    }
    ASSERT(create_member != NULL && create_member->is_static);
    ASSERT(map_member != NULL && map_member->is_static);
    ASSERT(secret_member != NULL && secret_member->is_static);
    ASSERT(bind_secret_member != NULL);

    sites[0] = nth_let_initializer(&exercise->as.function_decl, 0U);
    sites[1] = nth_let_initializer(&exercise->as.function_decl, 1U);
    ASSERT(sites[0] != NULL && sites[1] != NULL);
    ASSERT(sites[1]->kind == FENG_EXPR_CAST);
    sites[1] = sites[1]->as.cast.value;
    ASSERT(exercise->as.function_decl.body->statement_count == 3U);
    sites[2] = exercise->as.function_decl.body->statements[2]
                   ->as.return_value;
    ASSERT(sites[2] != NULL && sites[2]->kind == FENG_EXPR_CALL);
    ASSERT(sites[2]->as.call.arg_count == 1U);
    sites[2] = sites[2]->as.call.args[0];
    ASSERT(returned->as.function_decl.body->statement_count == 1U);
    sites[3] = returned->as.function_decl.body->statements[0]
                   ->as.return_value;

    for (size_t index = 0U; index < 4U; ++index) {
        const FengSpecCoercionSite *site =
            feng_semantic_lookup_spec_coercion_site(analysis, sites[index]);

        ASSERT(site != NULL);
        ASSERT(site->form == FENG_SPEC_COERCION_FORM_CALLABLE);
        ASSERT(site->callable_source ==
               FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE);
        ASSERT(site->target_spec_decl == creator);
        ASSERT(site->callable_member == create_member);
        ASSERT(site->callable_owner_type_decl == factory);
        ASSERT(site->callable_fit_decl == NULL);
        ASSERT(site->callable_type_arg_count == 0U);
        ASSERT(spec_upcast_type_ref_leaf_is(
            site->callable_receiver_type_ref, "T"));
    }

    {
        const FengReifiableDepSet *dep_set =
            feng_semantic_lookup_reifiable_dep_set(analysis, exercise);
        const FengReifiableCallableDep *dependency;

        ASSERT(dep_set != NULL);
        ASSERT(dep_set->callable_dep_count == 1U);
        dependency = &dep_set->callable_deps[0];
        ASSERT(dependency->purpose ==
               FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE);
        ASSERT(dependency->kind ==
               FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD);
        ASSERT(dependency->owner_type_decl == factory);
        ASSERT(dependency->member == create_member);
        ASSERT(dependency->fit_decl == NULL);
        ASSERT(spec_upcast_type_ref_leaf_is(
            dependency->owner_instance_type_ref, "T"));
        ASSERT(spec_upcast_type_ref_leaf_is(
            dependency->target_callable_type_ref, "Creator"));
    }
    {
        const FengReifiableDepSet *dep_set =
            feng_semantic_lookup_reifiable_dep_set(analysis, direct);

        ASSERT(dep_set == NULL || dep_set->callable_dep_count == 0U);
    }
    {
        const FengExpr *site_expr =
            inherited->as.function_decl.body->statements[0]
                ->as.return_value;
        const FengSpecCoercionSite *site =
            feng_semantic_lookup_spec_coercion_site(analysis, site_expr);
        const FengReifiableDepSet *dep_set =
            feng_semantic_lookup_reifiable_dep_set(analysis, inherited);

        ASSERT(site != NULL);
        ASSERT(site->target_spec_decl == int_mapper);
        ASSERT(site->callable_owner_type_decl == generic_factory);
        ASSERT(site->callable_member == map_member);
        ASSERT(spec_upcast_type_ref_leaf_is(
            site->callable_receiver_type_ref, "T"));
        ASSERT(dep_set != NULL && dep_set->callable_dep_count == 1U);
        ASSERT(dep_set->callable_deps[0].kind ==
               FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD);
        ASSERT(dep_set->callable_deps[0].owner_type_decl == generic_factory);
        ASSERT(dep_set->callable_deps[0].member == map_member);
    }
    {
        const FengExpr *site_expr =
            bind_secret_member->as.callable.body->statements[0]
                ->as.return_value;
        const FengSpecCoercionSite *site =
            feng_semantic_lookup_spec_coercion_site(analysis, site_expr);

        ASSERT(site != NULL);
        ASSERT(site->target_spec_decl == creator);
        ASSERT(site->callable_owner_type_decl == secret_factory);
        ASSERT(site->callable_member == secret_member);
        ASSERT(spec_upcast_type_ref_leaf_is(
            site->callable_receiver_type_ref, "T"));
    }

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* MV07: a T: IntersectionSpec static method value consumes the same exact
 * flattened requirement surface as IC01 while preserving MV04's receiver-free
 * callable dependency. Direct, parent, nested and overloaded requirements all
 * retain their declaring object spec and the caller-view owner T. */
static void test_intersection_constrained_static_method_values_record_surface(void) {
    const char *source =
        "module demo.intersection_static_method_value.surface;\n"
        "spec RootFactory<X> {\n"
        "  static func inherited(value: X): X;\n"
        "  static func duplicate(value: X): X;\n"
        "}\n"
        "spec NumberFactory: RootFactory<int> {\n"
        "  static func create(seed: int): int;\n"
        "  static func select(value: int): int;\n"
        "  static func duplicate(value: int): int;\n"
        "}\n"
        "spec TextFactory {\n"
        "  static func label(): string;\n"
        "  static func select(value: string): string;\n"
        "  static func duplicate(value: int): int;\n"
        "}\n"
        "spec CombinedFactory: NumberFactory & TextFactory;\n"
        "spec ExtraFactory { static func extra(value: int): int; }\n"
        "spec NestedFactory: CombinedFactory & ExtraFactory;\n"
        "spec IntMapper(value: int): int;\n"
        "spec StringMapper(value: string): string;\n"
        "spec StringSupplier(): string;\n"
        "func accept(supplier: StringSupplier): StringSupplier {\n"
        "  return supplier;\n"
        "}\n"
        "func exercise<T: NestedFactory>(): StringSupplier {\n"
        "  let create: IntMapper = T.create;\n"
        "  let inherited: IntMapper = T.inherited;\n"
        "  let extra = (IntMapper)T.extra;\n"
        "  let number: IntMapper = T.select;\n"
        "  let text: StringMapper = T.select;\n"
        "  let duplicate: IntMapper = T.duplicate;\n"
        "  return accept(T.label);\n"
        "}\n";
    static const struct {
        const char *owner_name;
        const char *member_name;
        size_t member_ordinal;
        const char *target_name;
    } cases[] = {
        {"NumberFactory", "create", 0U, "IntMapper"},
        {"RootFactory", "inherited", 0U, "IntMapper"},
        {"ExtraFactory", "extra", 0U, "IntMapper"},
        {"NumberFactory", "select", 0U, "IntMapper"},
        {"TextFactory", "select", 0U, "StringMapper"},
        {"NumberFactory", "duplicate", 0U, "IntMapper"},
        {"TextFactory", "label", 0U, "StringSupplier"}
    };
    FengProgram *program = parse_program_or_die(
        "intersection_constrained_static_method_value_surface.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *exercise;
    const FengExpr *sites[7];

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    exercise = find_function_decl_in_program(program, "exercise");
    ASSERT(exercise != NULL);
    for (size_t index = 0U; index < 6U; ++index) {
        sites[index] = nth_let_initializer(
            &exercise->as.function_decl, index);
        ASSERT(sites[index] != NULL);
    }
    ASSERT(sites[2]->kind == FENG_EXPR_CAST);
    sites[2] = sites[2]->as.cast.value;
    ASSERT(exercise->as.function_decl.body->statement_count == 7U);
    ASSERT(exercise->as.function_decl.body->statements[6]->kind ==
           FENG_STMT_RETURN);
    sites[6] = exercise->as.function_decl.body->statements[6]
                   ->as.return_value;
    ASSERT(sites[6] != NULL && sites[6]->kind == FENG_EXPR_CALL);
    ASSERT(sites[6]->as.call.arg_count == 1U);
    sites[6] = sites[6]->as.call.args[0];

    for (size_t index = 0U;
         index < sizeof(cases) / sizeof(cases[0]);
         ++index) {
        const FengDecl *owner = find_spec_decl_by_name(
            analysis, cases[index].owner_name);
        const FengDecl *target = find_spec_decl_by_name(
            analysis, cases[index].target_name);
        const FengTypeMember *member =
            find_object_spec_static_method_named_at(
                owner,
                cases[index].member_name,
                cases[index].member_ordinal);
        const FengSpecCoercionSite *site =
            feng_semantic_lookup_spec_coercion_site(
                analysis, sites[index]);

        ASSERT(owner != NULL && target != NULL && member != NULL);
        ASSERT(site != NULL);
        ASSERT(site->form == FENG_SPEC_COERCION_FORM_CALLABLE);
        ASSERT(site->callable_source ==
               FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE);
        ASSERT(site->target_spec_decl == target);
        ASSERT(site->callable_member == member);
        ASSERT(site->callable_owner_type_decl == owner);
        ASSERT(site->callable_fit_decl == NULL);
        ASSERT(site->callable_type_arg_count == 0U);
        ASSERT(spec_upcast_type_ref_leaf_is(
            site->callable_receiver_type_ref, "T"));
    }

    {
        const FengReifiableDepSet *dep_set =
            feng_semantic_lookup_reifiable_dep_set(analysis, exercise);

        ASSERT(dep_set != NULL);
        ASSERT(dep_set->callable_dep_count == 7U);
        for (size_t index = 0U;
             index < dep_set->callable_dep_count;
             ++index) {
            const FengReifiableCallableDep *dependency =
                &dep_set->callable_deps[index];

            ASSERT(dependency->purpose ==
                   FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE);
            ASSERT(dependency->kind ==
                   FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD);
            ASSERT(dependency->owner_type_decl != NULL);
            ASSERT(dependency->owner_type_decl->kind == FENG_DECL_SPEC);
            ASSERT(dependency->member != NULL);
            ASSERT(dependency->member->is_static);
            ASSERT(dependency->fit_decl == NULL);
            ASSERT(spec_upcast_type_ref_leaf_is(
                dependency->owner_instance_type_ref, "T"));
        }
    }

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* MV07 applies the declaring object spec's seal authorization after traversing
 * an intersection constraint, exactly as IC01 and MV04 do. */
static void test_intersection_constrained_static_method_values_allow_authorized_seal(void) {
    const char *source =
        "module demo.intersection_static_method_value.authorized;\n"
        "spec HiddenFactory {\n"
        "  @friend(Reader) seal static func secret(value: int): int;\n"
        "}\n"
        "spec VisibleFactory { static func visible(): int; }\n"
        "spec BothFactory: HiddenFactory & VisibleFactory;\n"
        "spec Mapper(value: int): int;\n"
        "type Reader {\n"
        "  static func bind<T: BothFactory>(): Mapper {\n"
        "    return T.secret;\n"
        "  }\n"
        "}\n";

    assert_single_source_semantic_ok(
        "intersection_static_method_value_authorized_seal.ff", source);
}

/* MV07 keeps the common callable-value diagnostics after the intersection
 * surface is enabled: missing target, signature mismatch and unauthorized
 * seal access all fail before code generation. Equivalent requirements are
 * covered by the positive surface test and must not create false ambiguity. */
static void test_intersection_constrained_static_method_values_reject_invalid_sources(void) {
    static const struct {
        const char *path;
        const char *source;
        const char *expected_code;
    } cases[] = {
        {
            "intersection_static_method_value_without_target.ff",
            "module demo.intersection_static_method_value.no_target;\n"
            "spec Factory { static func create(seed: int): int; }\n"
            "spec Tagged { static func tag(): string; }\n"
            "spec Both: Factory & Tagged;\n"
            "func bad<T: Both>(): void { let creator = T.create; }\n",
            "AE0523"
        },
        {
            "intersection_static_method_value_mismatch.ff",
            "module demo.intersection_static_method_value.mismatch;\n"
            "spec Factory { static func create(seed: int): int; }\n"
            "spec Tagged { static func tag(): string; }\n"
            "spec Both: Factory & Tagged;\n"
            "spec Wrong(flag: bool): int;\n"
            "func bad<T: Both>(): Wrong { return T.create; }\n",
            "AE0522"
        },
        {
            "intersection_static_method_value_seal_access.ff",
            "module demo.intersection_static_method_value.seal_access;\n"
            "spec HiddenFactory {\n"
            "  @friend(Reader) seal static func secret(value: int): int;\n"
            "}\n"
            "spec VisibleFactory { static func visible(): int; }\n"
            "spec BothFactory: HiddenFactory & VisibleFactory;\n"
            "spec Mapper(value: int): int;\n"
            "type Reader {}\n"
            "func bad<T: BothFactory>(): Mapper { return T.secret; }\n",
            "AE0708"
        }
    };

    for (size_t case_index = 0U;
         case_index < sizeof(cases) / sizeof(cases[0]);
         ++case_index) {
        FengProgram *program = parse_program_or_die(
            cases[case_index].path, cases[case_index].source);
        const FengProgram *programs[] = {program};
        FengSemanticAnalysis *analysis = NULL;
        FengSemanticError *errors = NULL;
        size_t error_count = 0U;

        ASSERT(!feng_semantic_analyze(programs, 1U,
                                      FENG_COMPILE_TARGET_LIB,
                                      &analysis,
                                      &errors,
                                      &error_count));
        ASSERT(semantic_error_code_count(
                   errors,
                   error_count,
                   cases[case_index].expected_code) == 1U);
        feng_semantic_errors_free(errors, error_count);
        feng_semantic_analysis_free(analysis);
        feng_program_free(program);
    }
}

/* A builtin fit can satisfy a static object-spec requirement. Closing either
 * a direct T.method() call or the corresponding method value must cache the
 * fit's static member in the same semantic witness slot. */
static void test_builtin_fit_static_spec_witness(void) {
    const char *source =
        "module demo.spec_static_method_value.builtin_fit_witness;\n"
        "spec Factory { static func create(seed: i32): i32; }\n"
        "spec Creator(seed: i32): i32;\n"
        "fit i32: Factory {\n"
        "    static func create(seed: i32): i32 { return seed + 1; }\n"
        "}\n"
        "func bind<T: Factory>(): Creator { return T.create; }\n"
        "func direct<T: Factory>(seed: i32): i32 { return T.create(seed); }\n"
        "func run(): i32 {\n"
        "    let creator = bind<i32>();\n"
        "    return creator(1) + direct<i32>(2);\n"
        "}\n";
    FengProgram *program = parse_program_or_die(
        "builtin_fit_static_spec_witness.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *factory;
    const FengDecl *fit;
    const FengTypeMember *requirement;
    const FengTypeMember *implementation;
    FengSemanticSubjectKey subject_key =
        feng_semantic_subject_key_for_builtin("i32");
    const FengSpecWitness *witness;

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    factory = find_spec_decl_by_name(analysis, "Factory");
    fit = program->declarations[2];
    ASSERT(factory != NULL);
    ASSERT(fit != NULL && fit->kind == FENG_DECL_FIT);
    ASSERT(factory->as.spec_decl.as.object.member_count == 1U);
    ASSERT(fit->as.fit_decl.member_count == 1U);
    requirement = factory->as.spec_decl.as.object.members[0];
    implementation = fit->as.fit_decl.members[0];
    ASSERT(requirement != NULL && requirement->is_static);
    ASSERT(implementation != NULL && implementation->is_static);

    witness = feng_semantic_lookup_spec_witness(
        analysis, &subject_key, factory);
    ASSERT(witness != NULL);
    ASSERT(witness->member_count == 1U);
    ASSERT(witness->members[0].spec_member == requirement);
    ASSERT(witness->members[0].impl_member == implementation);
    ASSERT(witness->members[0].source_kind ==
           FENG_SPEC_WITNESS_SOURCE_FIT_METHOD);
    ASSERT(witness->members[0].via_fit_decl == fit);

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

