/* Assert the common identity and path invariants of one recorded upcast. */
static const FengSpecCoercionSite *assert_object_spec_upcast_site(
    const FengSemanticAnalysis *analysis,
    const FengExpr *expr,
    const FengDecl *target_spec,
    const size_t *parent_indices,
    size_t parent_index_count) {
    const FengSpecCoercionSite *site =
        feng_semantic_lookup_spec_coercion_site(analysis, expr);

    ASSERT(site != NULL);
    ASSERT(site->form == FENG_SPEC_COERCION_FORM_OBJECT_UPCAST);
    ASSERT(site->target_spec_decl == target_spec);
    ASSERT(site->target_spec_type_ref != NULL);
    ASSERT(site->object_upcast_parent_indices != NULL);
    ASSERT(site->object_upcast_parent_index_count == parent_index_count);
    for (size_t index = 0U; index < parent_index_count; ++index) {
        ASSERT(site->object_upcast_parent_indices[index] == parent_indices[index]);
    }
    ASSERT(site->relation == NULL);
    return site;
}

/* Direct, transitive, source-order diamond, explicit, and generic paths are
 * recorded as direct-parent declaration-index sequences. */
static void test_object_spec_upcast_records_selected_parent_paths(void) {
    const char *source =
        "module demo.spec_upcast.paths;\n"
        "type Box<T> { let value: T; }\n"
        "spec Root {}\n"
        "spec Left: Root {}\n"
        "spec Right: Root {}\n"
        "spec Diamond: Left, Right {}\n"
        "spec GenericParent<T> {}\n"
        "spec GenericChild<T>: GenericParent<T> {}\n"
        "spec MappedChild<T>: GenericParent<Box<T>> {}\n"
        "func exercise(d: Diamond, c: GenericChild<i32>, m: MappedChild<i32>) {\n"
        "    let direct: Left = d;\n"
        "    let transitive: Root = d;\n"
        "    let right: Right = d;\n"
        "    let explicit = (Root)d;\n"
        "    let generic: GenericParent<i32> = c;\n"
        "    let mapped: GenericParent<Box<i32>> = m;\n"
        "}\n";
    FengProgram *program = parse_program_or_die("spec_upcast_paths.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *exercise;
    const FengDecl *root;
    const FengDecl *left;
    const FengDecl *right;
    const FengDecl *generic_parent;
    const FengExpr *initializer;
    const FengSpecCoercionSite *site;
    const size_t left_path[] = {0U};
    const size_t root_path[] = {0U, 0U};
    const size_t right_path[] = {1U};

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    exercise = find_function_decl_in_program(program, "exercise");
    root = find_spec_decl_by_name(analysis, "Root");
    left = find_spec_decl_by_name(analysis, "Left");
    right = find_spec_decl_by_name(analysis, "Right");
    generic_parent = find_spec_decl_by_name(analysis, "GenericParent");
    ASSERT(exercise != NULL && root != NULL && left != NULL && right != NULL);
    ASSERT(generic_parent != NULL);

    initializer = nth_let_initializer(&exercise->as.function_decl, 0U);
    site = assert_object_spec_upcast_site(analysis, initializer,
                                          left, left_path, 1U);

    initializer = nth_let_initializer(&exercise->as.function_decl, 1U);
    site = assert_object_spec_upcast_site(analysis, initializer,
                                          root, root_path, 2U);

    initializer = nth_let_initializer(&exercise->as.function_decl, 2U);
    site = assert_object_spec_upcast_site(analysis, initializer,
                                          right, right_path, 1U);

    initializer = nth_let_initializer(&exercise->as.function_decl, 3U);
    ASSERT(initializer != NULL && initializer->kind == FENG_EXPR_CAST);
    site = assert_object_spec_upcast_site(analysis,
                                          initializer->as.cast.value,
                                          root, root_path, 2U);
    ASSERT(feng_semantic_lookup_spec_coercion_site(analysis, initializer) == NULL);

    initializer = nth_let_initializer(&exercise->as.function_decl, 4U);
    site = assert_object_spec_upcast_site(analysis, initializer,
                                          generic_parent, left_path, 1U);
    ASSERT(spec_upcast_type_ref_leaf_is(site->target_spec_type_ref,
                                        "GenericParent"));
    ASSERT(site->target_spec_type_ref->as.named.type_arg_count == 1U);
    ASSERT(spec_upcast_type_ref_leaf_is(
        site->target_spec_type_ref->as.named.type_args[0], "i32"));

    initializer = nth_let_initializer(&exercise->as.function_decl, 5U);
    site = assert_object_spec_upcast_site(analysis, initializer,
                                          generic_parent, left_path, 1U);
    ASSERT(spec_upcast_type_ref_leaf_is(site->target_spec_type_ref,
                                        "GenericParent"));
    ASSERT(site->target_spec_type_ref->as.named.type_arg_count == 1U);
    ASSERT(spec_upcast_type_ref_leaf_is(
        site->target_spec_type_ref->as.named.type_args[0], "Box"));
    ASSERT(site->target_spec_type_ref->as.named.type_args[0]
               ->as.named.type_arg_count == 1U);
    ASSERT(spec_upcast_type_ref_leaf_is(
        site->target_spec_type_ref->as.named.type_args[0]
            ->as.named.type_args[0],
        "i32"));

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* The existing overload ordering keeps an exact child parameter ahead of an
 * applicable parent parameter, and records only the selected parent's cast. */
static void test_object_spec_upcast_preserves_current_overload_priority(void) {
    const char *source =
        "module demo.spec_upcast.overload;\n"
        "spec Parent {}\n"
        "spec Child: Parent {}\n"
        "func choose(value: Child): i32 { return 1; }\n"
        "func choose(value: Parent): i32 { return 2; }\n"
        "func exact(value: Child): i32 { return choose(value); }\n"
        "func parent(value: Child): i32 { return choose((Parent)value); }\n";
    FengProgram *program = parse_program_or_die("spec_upcast_overload.ff", source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    const FengDecl *exact;
    const FengDecl *parent;
    const FengExpr *exact_call;
    const FengExpr *parent_call;
    const FengExpr *parent_cast;
    const size_t direct_parent_path[] = {0U};

    ASSERT(feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                 &analysis, &errors, &error_count));
    ASSERT(error_count == 0U);
    exact = find_function_decl_in_program(program, "exact");
    parent = find_function_decl_in_program(program, "parent");
    ASSERT(exact != NULL && parent != NULL);
    exact_call = exact->as.function_decl.body->statements[0]->as.return_value;
    parent_call = parent->as.function_decl.body->statements[0]->as.return_value;
    ASSERT(exact_call != NULL && exact_call->kind == FENG_EXPR_CALL);
    ASSERT(parent_call != NULL && parent_call->kind == FENG_EXPR_CALL);
    ASSERT(exact_call->as.call.resolved_callable.kind ==
           FENG_RESOLVED_CALLABLE_FUNCTION);
    ASSERT(parent_call->as.call.resolved_callable.kind ==
           FENG_RESOLVED_CALLABLE_FUNCTION);
    ASSERT(spec_upcast_type_ref_leaf_is(
        exact_call->as.call.resolved_callable.function_decl
            ->as.function_decl.params[0].type,
        "Child"));
    ASSERT(spec_upcast_type_ref_leaf_is(
        parent_call->as.call.resolved_callable.function_decl
            ->as.function_decl.params[0].type,
        "Parent"));
    ASSERT(feng_semantic_lookup_spec_coercion_site(
               analysis, exact_call->as.call.args[0]) == NULL);
    parent_cast = parent_call->as.call.args[0];
    ASSERT(parent_cast != NULL && parent_cast->kind == FENG_EXPR_CAST);
    ASSERT(assert_object_spec_upcast_site(
               analysis,
               parent_cast->as.cast.value,
               find_spec_decl_by_name(analysis, "Parent"),
               direct_parent_path,
               1U) != NULL);

    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Assert that one rejected source contains the expected stable diagnostic. */
static void assert_object_spec_upcast_error_code(const char *path,
                                                 const char *source,
                                                 const char *expected_code) {
    FengProgram *program = parse_program_or_die(path, source);
    const FengProgram *programs[] = {program};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    bool found = false;

    ASSERT(!feng_semantic_analyze(programs, 1U, FENG_COMPILE_TARGET_LIB,
                                  &analysis, &errors, &error_count));
    ASSERT(error_count > 0U);
    for (size_t error_index = 0U;
         error_index < error_count;
         ++error_index) {
        if (strcmp(errors[error_index].code, expected_code) == 0) {
            found = true;
            break;
        }
    }
    ASSERT(found);
    feng_semantic_errors_free(errors, error_count);
    feng_semantic_analysis_free(analysis);
    feng_program_free(program);
}

/* Upcasting does not permit downcasts, unrelated spec views, runtime-subject
 * guesses, generic variance, or unresolved same-rank overload candidates. */
static void test_object_spec_upcast_rejects_out_of_scope_conversions(void) {
    const char *downcast =
        "module demo.spec_upcast.downcast;\n"
        "spec Parent {}\n"
        "spec Child: Parent {}\n"
        "func bad(value: Parent) { let child: Child = value; }\n";
    const char *unrelated =
        "module demo.spec_upcast.unrelated;\n"
        "spec First {}\n"
        "spec Second {}\n"
        "type Both: First, Second {}\n"
        "func bad(value: First) { let second: Second = value; }\n";
    const char *variance =
        "module demo.spec_upcast.variance;\n"
        "spec Animal {}\n"
        "spec Dog: Animal {}\n"
        "spec Parent<T> {}\n"
        "func bad(value: Parent<Dog>) { let parent: Parent<Animal> = value; }\n";
    const char *explicit_downcast =
        "module demo.spec_upcast.explicit_downcast;\n"
        "spec Parent {}\n"
        "spec Child: Parent {}\n"
        "func bad(value: Parent) { let child = (Child)value; }\n";
    const char *explicit_unrelated =
        "module demo.spec_upcast.explicit_unrelated;\n"
        "spec First {}\n"
        "spec Second {}\n"
        "func bad(value: First) { let second = (Second)value; }\n";
    const char *ambiguous =
        "module demo.spec_upcast.ambiguous;\n"
        "spec Root {}\n"
        "spec Left: Root {}\n"
        "spec Right: Root {}\n"
        "spec Both: Left, Right {}\n"
        "func choose(value: Left): i32 { return 1; }\n"
        "func choose(value: Right): i32 { return 2; }\n"
        "func bad(value: Both): i32 { return choose(value); }\n";

    assert_object_spec_upcast_error_code("spec_upcast_downcast.ff",
                                         downcast, "AE1003");
    assert_object_spec_upcast_error_code("spec_upcast_unrelated.ff",
                                         unrelated, "AE1003");
    assert_object_spec_upcast_error_code("spec_upcast_variance.ff",
                                         variance, "AE1003");
    assert_object_spec_upcast_error_code("spec_upcast_explicit_downcast.ff",
                                         explicit_downcast, "AE1023");
    assert_object_spec_upcast_error_code("spec_upcast_explicit_unrelated.ff",
                                         explicit_unrelated, "AE1023");
    assert_object_spec_upcast_error_code("spec_upcast_ambiguous.ff",
                                         ambiguous, "AE0511");
}

/* Friend authorization covers all concrete type member shapes, merges
 * repeated annotations, and is independent of source declaration order. */
static void test_friend_type_member_access_and_normalization(void) {
    const char *source =
        "open module demo.friend.type_access;\n"
        "open type Helper {\n"
        "  func inspect(vault: Vault): int {\n"
        "    vault.value = vault.value + 1;\n"
        "    Vault.shared = Vault.shared + 1;\n"
        "    return vault.value + vault.read() + Vault.shared + Vault.readShared();\n"
        "  }\n"
        "  static func inspectStatic(vault: Vault): int { return vault.read(); }\n"
        "}\n"
        "open type Vault {\n"
        "  @friend(Helper)\n"
        "  @friend(demo.friend.type_access.Helper)\n"
        "  seal var value: int;\n"
        "  @friend(Helper) seal static var shared: int = 2;\n"
        "  @friend(Helper) seal func read(): int { return self.value; }\n"
        "  @friend(Helper) seal static func readShared(): int { return Vault.shared; }\n"
        "  func Vault(value: int) { self.value = value; }\n"
        "}\n";

    assert_single_source_semantic_ok("friend_type_access.ff", source);
}

/* A friend type's lexical implementation owner authorizes field initializers,
 * constructors, finalizers, and nested lambdas in addition to ordinary
 * instance/static methods. Calls and method values share the same predicate. */
static void test_friend_type_implementation_contexts_are_authorized(void) {
    const char *source =
        "module demo.friend.implementation_contexts;\n"
        "spec Producer(): int;\n"
        "type Vault {\n"
        "  @friend(Reader) seal let value: int;\n"
        "  @friend(Reader) seal static let shared: int = 11;\n"
        "  func Vault(value: int) { self.value = value; }\n"
        "  @friend(Reader) seal func read(): int { return self.value; }\n"
        "  @friend(Reader) seal static func readShared(): int { return Vault.shared; }\n"
        "}\n"
        "type Reader {\n"
        "  let initializedField: int = Vault(1).value;\n"
        "  static let initializedStaticField: int = Vault.shared;\n"
        "  let initializedCall: int = Vault(2).read();\n"
        "  static let initializedStaticCall: int = Vault.readShared();\n"
        "  let initializedMethod: Producer = Vault(3).read;\n"
        "  let initializedLambda: Producer = () -> Vault(4).read();\n"
        "  seal let retained: Vault;\n"
        "  func Reader(vault: Vault) {\n"
        "    self.retained = vault;\n"
        "    vault.value;\n"
        "    Vault.shared;\n"
        "    vault.read();\n"
        "    Vault.readShared();\n"
        "    let method: Producer = vault.read;\n"
        "    let nested: Producer = () -> vault.read();\n"
        "    method(); nested();\n"
        "  }\n"
        "  func ~Reader() {\n"
        "    self.retained.value;\n"
        "    Vault.shared;\n"
        "    self.retained.read();\n"
        "    Vault.readShared();\n"
        "    let method: Producer = self.retained.read;\n"
        "    let nested: Producer = () -> Vault(5).read();\n"
        "    method(); nested();\n"
        "  }\n"
        "}\n";

    assert_single_source_semantic_ok("friend_implementation_contexts.ff", source);
}

/* A fully qualified friend identity works across local modules from field,
 * constructor, and finalizer contexts; source order does not affect the
 * package-local friend metadata pre-pass. */
static void test_friend_type_implementation_contexts_cross_module(void) {
    const char *reader_source =
        "open module demo.friend.context_reader;\n"
        "import demo.friend.context_owner;\n"
        "open type Reader {\n"
        "  let initialized: int = Vault().secret();\n"
        "  func Reader(vault: Vault) {\n"
        "    let method: Producer = vault.secret;\n"
        "    method();\n"
        "  }\n"
        "  func ~Reader() { Vault().secret(); }\n"
        "}\n";
    const char *owner_source =
        "open module demo.friend.context_owner;\n"
        "open spec Producer(): int;\n"
        "open type Vault {\n"
        "  @friend(demo.friend.context_reader.Reader)\n"
        "  seal func secret(): int { return 17; }\n"
        "}\n";
    FengProgram *reader = parse_program_or_die(
        "friend_context_reader.ff", reader_source);
    FengProgram *owner = parse_program_or_die(
        "friend_context_owner.ff", owner_source);
    const FengProgram *programs[] = {reader, owner};
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;

    ASSERT(feng_semantic_analyze(programs,
                                 2U,
                                 FENG_COMPILE_TARGET_LIB,
                                 &analysis,
                                 &errors,
                                 &error_count));
    ASSERT(error_count == 0U);
    feng_semantic_analysis_free(analysis);
    feng_program_free(reader);
    feng_program_free(owner);
}

/* The lexical implementation owner remains exact: unrelated types, top-level
 * code, and mismatched generic friend instances do not gain authorization in
 * any newly accepted context. */
static void test_friend_type_implementation_contexts_remain_exact(void) {
    static const char *rejected[] = {
        "module demo.friend.context_bad_field; type Reader {} type Vault { @friend(Reader) seal func secret(): int { return 1; } } type Other { let value: int = Vault().secret(); }",
        "module demo.friend.context_bad_constructor; type Reader {} type Vault { @friend(Reader) seal func secret(): int { return 1; } } type Other { func Other(vault: Vault) { vault.secret(); } }",
        "module demo.friend.context_bad_finalizer; type Reader {} type Vault { @friend(Reader) seal func secret(): int { return 1; } } type Other { func ~Other() { Vault().secret(); } }",
        "module demo.friend.context_bad_lambda; spec Producer(): int; type Reader {} type Vault { @friend(Reader) seal func secret(): int { return 1; } } type Other { let value: Producer = () -> Vault().secret(); }",
        "module demo.friend.context_bad_binding; type Reader {} type Vault { @friend(Reader) seal static func secret(): int { return 1; } } let value: int = Vault.secret();",
        "module demo.friend.context_bad_function; type Reader {} type Vault { @friend(Reader) seal func secret(): int { return 1; } } func read(vault: Vault): int { return vault.secret(); }",
        "module demo.friend.context_bad_generic; type Reader<T> { let marker: int = Vault<string>.secret(); } type Vault<T> { @friend(Reader<T>) seal static func secret(): int { return 1; } }"
    };

    for (size_t index = 0U;
         index < sizeof(rejected) / sizeof(rejected[0]);
         ++index) {
        assert_single_source_semantic_error_contains(
            "friend_context_rejected.ff", rejected[index], "not accessible");
    }
}

